files.content:
//! Deriving a snapshot graph from a real Iceberg table.
//!
//! The table here is genuine: real metadata JSON, real Avro manifest lists and
//! manifests, written with `iceberg-rust`'s own writers and read back through
//! its own readers. Only the Parquet data files are absent, because the bridge
//! never opens them — it reads metadata, which is exactly the point.
//!
//! ```sh
//! cargo test --features iceberg --test iceberg_bridge
//! ```

#![cfg(feature = "iceberg")]

use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};

use iceberg::io::FileIO;
use iceberg::spec::{
    DataContentType, DataFileBuilder, DataFileFormat, ManifestListWriter, ManifestWriterBuilder,
    Struct, TableMetadata,
};

use quarry::from_iceberg::{current_snapshot, live_data_files, snapshot_graph, table_id};
use quarry::snapshot::{DeleteState, FileId, SnapshotId};

/// One data or delete file to record in a snapshot.
struct Entry {
    path: &'static str,
    content: DataContentType,
}

fn data(path: &'static str) -> Entry {
    Entry {
        path,
        content: DataContentType::Data,
    }
}

fn position_deletes(path: &'static str) -> Entry {
    Entry {
        path,
        content: DataContentType::PositionDeletes,
    }
}

/// A directory of its own per test.
fn scratch(name: &str) -> PathBuf {
    let dir = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(name);
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(dir.join("metadata")).expect("create scratch dir");
    dir
}

/// Metadata for a table whose snapshots are 1 → 2 → 3, unpartitioned.
fn metadata_json(dir: &Path, snapshots: usize) -> String {
    let location = dir.to_string_lossy();
    let entries: Vec<String> = (1..=snapshots)
        .map(|id| {
            let parent = if id > 1 {
                format!(r#""parent-snapshot-id": {},"#, id - 1)
            } else {
                String::new()
            };
            format!(
                r#"{{
                    "snapshot-id": {id},
                    {parent}
                    "sequence-number": {id},
                    "timestamp-ms": {id},
                    "summary": {{"operation": "append"}},
                    "manifest-list": "{location}/metadata/list-{id}.avro",
                    "schema-id": 0
                }}"#
            )
        })
        .collect();

    format!(
        r#"{{
            "format-version": 2,
            "table-uuid": "9c12d441-03fe-4693-9a96-a0705ddf69c1",
            "location": "{location}",
            "last-sequence-number": {snapshots},
            "last-updated-ms": 1,
            "last-column-id": 2,
            "current-schema-id": 0,
            "schemas": [{{
                "type": "struct",
                "schema-id": 0,
                "fields": [
                    {{"id": 1, "name": "tenant_id", "required": true, "type": "long"}},
                    {{"id": 2, "name": "message", "required": true, "type": "string"}}
                ]
            }}],
            "default-spec-id": 0,
            "partition-specs": [{{"spec-id": 0, "fields": []}}],
            "last-partition-id": 999,
            "default-sort-order-id": 0,
            "sort-orders": [{{"order-id": 0, "fields": []}}],
            "properties": {{}},
            "current-snapshot-id": {snapshots},
            "snapshots": [{}],
            "snapshot-log": [],
            "metadata-log": [],
            "refs": {{"main": {{"snapshot-id": {snapshots}, "type": "branch"}}}}
        }}"#,
        entries.join(",")
    )
}

/// Write the manifest list and manifest for one snapshot.
async fn write_snapshot(
    dir: &Path,
    file_io: &FileIO,
    metadata: &TableMetadata,
    snapshot_id: i64,
    entries: &[Entry],
) {
    let schema = metadata.current_schema().clone();
    let spec = metadata.default_partition_spec().as_ref().clone();

    let build = |kind: &str| {
        ManifestWriterBuilder::new(
            file_io
                .new_output(format!(
                    "{}/metadata/manifest-{snapshot_id}-{kind}.avro",
                    dir.to_string_lossy()
                ))
                .expect("manifest output"),
            Some(snapshot_id),
            None,
            schema.clone(),
            spec.clone(),
        )
    };

    let file_of = |entry: &Entry| {
        DataFileBuilder::default()
            .partition_spec_id(0)
            .content(entry.content)
            .file_path(entry.path.to_owned())
            .file_format(DataFileFormat::Parquet)
            .file_size_in_bytes(1000)
            .record_count(10)
            .partition(Struct::empty())
            .build()
            .expect("data file")
    };

    // Iceberg keeps data files and delete files in manifests of different
    // content types, so a snapshot with both needs two manifests. The bridge
    // has to read both kinds, which is exactly what this exercises.
    let mut manifests = Vec::new();

    let data_entries: Vec<&Entry> = entries
        .iter()
        .filter(|entry| entry.content == DataContentType::Data)
        .collect();
    if !data_entries.is_empty() {
        let mut writer = build("data").build_v2_data();
        for entry in data_entries {
            writer
                .add_file(file_of(entry), snapshot_id)
                .expect("add data file");
        }
        manifests.push(writer.write_manifest_file().await.expect("write data"));
    }

    let delete_entries: Vec<&Entry> = entries
        .iter()
        .filter(|entry| entry.content != DataContentType::Data)
        .collect();
    if !delete_entries.is_empty() {
        let mut writer = build("deletes").build_v2_deletes();
        for entry in delete_entries {
            // `add_file`, not `add_delete_file`. The latter reads as though it
            // adds a delete file, but it sets the entry's status to `Deleted`,
            // which per the spec means "this file was REMOVED from the table".
            // A delete file that is live in the snapshot is an `Added` entry in
            // a deletes-content manifest.
            writer
                .add_file(file_of(entry), snapshot_id)
                .expect("add delete file");
        }
        manifests.push(writer.write_manifest_file().await.expect("write deletes"));
    }

    let list_path = format!("{}/metadata/list-{snapshot_id}.avro", dir.to_string_lossy());
    let mut list = ManifestListWriter::v2(
        file_io.new_output(&list_path).expect("list output"),
        snapshot_id,
        if snapshot_id > 1 {
            Some(snapshot_id - 1)
        } else {
            None
        },
        snapshot_id,
    );
    list.add_manifests(manifests.into_iter())
        .expect("add manifests");
    list.close().await.expect("close list");
}

/// Build a table whose snapshot `n` holds `snapshots[n - 1]`.
async fn table(name: &str, snapshots: &[Vec<Entry>]) -> (TableMetadata, FileIO) {
    let dir = scratch(name);
    let file_io = FileIO::from_path(dir.to_str().expect("utf-8 path"))
        .expect("file io")
        .build()
        .expect("build file io");

    let metadata: TableMetadata =
        serde_json::from_str(&metadata_json(&dir, snapshots.len())).expect("valid metadata");

    for (index, entries) in snapshots.iter().enumerate() {
        write_snapshot(&dir, &file_io, &metadata, index as i64 + 1, entries).await;
    }

    (metadata, file_io)
}

fn f(path: &str) -> FileId {
    FileId(path.to_owned())
}

#[tokio::test]
async fn the_table_uuid_is_the_table_identity() {
    let (metadata, _) = table("iceberg_identity", &[vec![data("a.parquet")]]).await;
    assert_eq!(
        table_id(&metadata).0,
        "9c12d441-03fe-4693-9a96-a0705ddf69c1",
        "identity must be the uuid, so renaming a table does not orphan \
         derived state"
    );
    assert_eq!(current_snapshot(&metadata), Some(SnapshotId(1)));
}

#[tokio::test]
async fn lineage_comes_from_parent_snapshot_ids() {
    let (metadata, file_io) = table(
        "iceberg_lineage",
        &[
            vec![data("a.parquet")],
            vec![data("a.parquet"), data("b.parquet")],
            vec![data("a.parquet"), data("b.parquet"), data("c.parquet")],
        ],
    )
    .await;

    let graph = snapshot_graph(&metadata, &file_io)
        .await
        .expect("build graph");

    assert!(graph.is_descendant_or_self(SnapshotId(3), SnapshotId(1)));
    assert!(graph.is_descendant_or_self(SnapshotId(3), SnapshotId(2)));
    assert!(!graph.is_descendant_or_self(SnapshotId(1), SnapshotId(3)));
}

#[tokio::test]
async fn live_files_come_from_the_manifests() {
    let (metadata, file_io) = table(
        "iceberg_live_files",
        &[
            vec![data("a.parquet")],
            vec![data("a.parquet"), data("b.parquet")],
        ],
    )
    .await;

    let graph = snapshot_graph(&metadata, &file_io)
        .await
        .expect("build graph");

    let at_one: BTreeSet<FileId> = graph
        .get(SnapshotId(1))
        .expect("snapshot 1")
        .files()
        .keys()
        .cloned()
        .collect();
    assert_eq!(at_one, BTreeSet::from([f("a.parquet")]));

    let at_two: BTreeSet<FileId> = graph
        .get(SnapshotId(2))
        .expect("snapshot 2")
        .files()
        .keys()
        .cloned()
        .collect();
    assert_eq!(at_two, BTreeSet::from([f("a.parquet"), f("b.parquet")]));
}

#[tokio::test]
async fn an_append_only_table_diffs_as_purely_additive() {
    let (metadata, file_io) = table(
        "iceberg_append",
        &[
            vec![data("a.parquet")],
            vec![data("a.parquet"), data("b.parquet")],
        ],
    )
    .await;

    let graph = snapshot_graph(&metadata, &file_io)
        .await
        .expect("build graph");

    let diff = graph
        .diff(SnapshotId(1), SnapshotId(2))
        .expect("both snapshots known");
    assert_eq!(diff.added, BTreeSet::from([f("b.parquet")]));
    assert!(
        diff.is_purely_additive(),
        "an append must leave substituting derived state usable"
    );
}

#[tokio::test]
async fn a_delete_file_shows_up_as_subtractive_change() {
    // Snapshot 2 adds a position delete file. No data file was added or
    // removed, so a file-set diff alone would see nothing at all.
    let (metadata, file_io) = table(
        "iceberg_deletes",
        &[
            vec![data("a.parquet")],
            vec![data("a.parquet"), position_deletes("d.parquet")],
        ],
    )
    .await;

    let graph = snapshot_graph(&metadata, &file_io)
        .await
        .expect("build graph");

    let one = graph.get(SnapshotId(1)).expect("snapshot 1");
    let two = graph.get(SnapshotId(2)).expect("snapshot 2");
    assert_eq!(
        one.files().get(&f("a.parquet")),
        Some(&DeleteState::NONE),
        "nothing is deleted at snapshot 1"
    );
    assert_ne!(
        two.files().get(&f("a.parquet")),
        Some(&DeleteState::NONE),
        "the delete file must change the data file's delete state"
    );

    // The delete file itself is not a data file.
    assert_eq!(
        two.files().keys().cloned().collect::<BTreeSet<_>>(),
        BTreeSet::from([f("a.parquet")])
    );

    let diff = graph
        .diff(SnapshotId(1), SnapshotId(2))
        .expect("both snapshots known");
    assert!(diff.added.is_empty(), "no data file was added");
    assert_eq!(diff.redeleted, BTreeSet::from([f("a.parquet")]));
    assert!(
        !diff.is_purely_additive(),
        "a delete must disqualify substituting derived state"
    );
}

#[tokio::test]
async fn compaction_shows_up_as_files_removed() {
    let (metadata, file_io) = table(
        "iceberg_compaction",
        &[
            vec![data("small-1.parquet"), data("small-2.parquet")],
            vec![data("merged.parquet")],
        ],
    )
    .await;

    let graph = snapshot_graph(&metadata, &file_io)
        .await
        .expect("build graph");

    let diff = graph
        .diff(SnapshotId(1), SnapshotId(2))
        .expect("both snapshots known");
    assert_eq!(diff.added, BTreeSet::from([f("merged.parquet")]));
    assert_eq!(
        diff.removed,
        BTreeSet::from([f("small-1.parquet"), f("small-2.parquet")])
    );
    assert!(!diff.is_purely_additive());
}

#[tokio::test]
async fn file_sizes_are_reported_for_registering_objects() {
    let (metadata, file_io) = table(
        "iceberg_sizes",
        &[vec![data("a.parquet"), data("b.parquet")]],
    )
    .await;

    let sizes = live_data_files(&metadata, &file_io, SnapshotId(1))
        .await
        .expect("read sizes");
    assert_eq!(sizes.len(), 2);
    assert_eq!(sizes.get(&f("a.parquet")), Some(&1000));
}

#[tokio::test]
async fn an_unknown_snapshot_yields_no_files_rather_than_an_error() {
    let (metadata, file_io) = table("iceberg_unknown", &[vec![data("a.parquet")]]).await;
    let sizes = live_data_files(&metadata, &file_io, SnapshotId(999))
        .await
        .expect("no error");
    assert!(sizes.is_empty());
}

//! Joins served from a cached build-side relation — the plan-level half of
//! the rule, for the `JOIN ... ON` shape.
//!
//! A scan never sees the join, so all of this goes through `Session::sql`:
//! the shape is recognised in the logical plan, the registry decides
//! whether a join hash may serve it, and the build-side `TableScan` is
//! swapped for a `MemTable` of stored rows.
//!
//! ```sh
//! cargo test --features engine --test join
//! ```

#![cfg(feature = "engine")]

use std::collections::BTreeMap;
use std::sync::Arc;

use datafusion::arrow::array::{Int64Array, RecordBatch, StringArray};
use datafusion::arrow::datatypes::{DataType, Field, Schema, SchemaRef};
use url::Url;

use quarry::derived::{Derived, DerivedId, PolicyFingerprint, Source};
use quarry::engine::{Quarry, QuarryTable, Session};
use quarry::kinds::JoinHash;
use quarry::registry::Registry;
use quarry::snapshot::{FileId, Snapshot, SnapshotGraph, SnapshotId, TableId};

const ORDER_ID: u32 = 1;
const CUSTOMER_ID: u32 = 2;
const CUSTOMER_NAME: u32 = 3;
const POLICY: PolicyFingerprint = PolicyFingerprint(1);

/// `orders(order_id, customer_id)` — the fact table, probe side.
fn orders_schema() -> SchemaRef {
    Arc::new(Schema::new(vec![
        Field::new("order_id", DataType::Int64, false),
        Field::new("customer_id", DataType::Int64, false),
    ]))
}

fn orders_field_ids() -> BTreeMap<String, u32> {
    BTreeMap::from([
        ("order_id".to_owned(), ORDER_ID),
        ("customer_id".to_owned(), CUSTOMER_ID),
    ])
}

/// `customers(customer_id, name)` — the dimension table, build side.
fn customers_schema() -> SchemaRef {
    Arc::new(Schema::new(vec![
        Field::new("customer_id", DataType::Int64, false),
        Field::new("name", DataType::Utf8, false),
    ]))
}

fn customers_field_ids() -> BTreeMap<String, u32> {
    BTreeMap::from([
        ("customer_id".to_owned(), CUSTOMER_ID),
        ("name".to_owned(), CUSTOMER_NAME),
    ])
}

/// Three orders for two customers.
fn orders_batch() -> RecordBatch {
    let order_ids = Int64Array::from(vec![100, 200, 300]);
    let customer_ids = Int64Array::from(vec![1, 2, 1]);
    RecordBatch::try_new(
        orders_schema(),
        vec![Arc::new(order_ids), Arc::new(customer_ids)],
    )
    .expect("orders batch")
}

/// Two customers.
fn customers_batch() -> RecordBatch {
    let customer_ids = Int64Array::from(vec![1, 2]);
    let names = StringArray::from(vec!["Alice", "Bob"]);
    RecordBatch::try_new(
        customers_schema(),
        vec![Arc::new(customer_ids), Arc::new(names)],
    )
    .expect("customers batch")
}

fn graph(at: SnapshotId) -> SnapshotGraph {
    SnapshotGraph::new().with(Snapshot::root(at).with_clean_file(FileId("a".into())))
}

fn orders_table(at: SnapshotId) -> QuarryTable {
    QuarryTable::new(
        orders_schema(),
        TableId("orders".into()),
        at,
        graph(at),
        orders_field_ids(),
    )
    .with_policy(POLICY)
    .with_file(FileId("a".into()), vec![orders_batch()])
}

fn customers_table(at: SnapshotId) -> QuarryTable {
    QuarryTable::new(
        customers_schema(),
        TableId("customers".into()),
        at,
        graph(at),
        customers_field_ids(),
    )
    .with_policy(POLICY)
    .with_file(FileId("a".into()), vec![customers_batch()])
}

/// A join hash over `customers.customer_id`, covering `customer_id` and
/// `name`, with the table's rows stored beside it.
fn join_hash(id: &str, at: SnapshotId) -> Derived {
    Derived::new(
        DerivedId(id.to_owned()),
        Source {
            table: TableId("customers".into()),
            snapshot: at,
        },
        POLICY,
        4096,
        Box::new(JoinHash::covering(
            [CUSTOMER_ID],
            [CUSTOMER_ID, CUSTOMER_NAME],
            4096,
        )),
    )
}

fn session() -> Session {
    Quarry::new(
        Url::parse("memory://").expect("url"),
        Arc::new(object_store::memory::InMemory::new()),
    )
    .session()
}

/// A customers table with a usable join hash, rows supplied.
fn with_hash() -> Arc<QuarryTable> {
    let mut registry = Registry::new();
    registry.register(join_hash("jh", SnapshotId(810)));
    Arc::new(
        customers_table(SnapshotId(810))
            .with_registry(registry)
            .with_projection(DerivedId("jh".into()), vec![customers_batch()]),
    )
}

/// The `(order_id, customer_name)` pairs of an answer, in the order they
/// came back.
fn pairs(batches: &[RecordBatch]) -> Vec<(i64, String)> {
    let mut out = Vec::new();
    for batch in batches {
        let order_ids = batch
            .column_by_name("order_id")
            .expect("order_id")
            .as_any()
            .downcast_ref::<Int64Array>()
            .expect("int64");
        let names = batch
            .column_by_name("name")
            .expect("name")
            .as_any()
            .downcast_ref::<StringArray>()
            .expect("utf8");
        for row in 0..batch.num_rows() {
            out.push((order_ids.value(row), names.value(row).to_owned()));
        }
    }
    out
}

#[tokio::test]
async fn a_join_is_served_by_a_join_hash() {
    let customers = with_hash();
    let orders = Arc::new(orders_table(SnapshotId(810)));
    let session = session();
    session
        .register("orders", Arc::clone(&orders))
        .expect("reg");
    session
        .register("customers", Arc::clone(&customers))
        .expect("reg");

    let rows = session
        .sql(
            "SELECT o.order_id, c.name \
             FROM customers AS c \
             INNER JOIN orders AS o ON c.customer_id = o.customer_id \
             ORDER BY o.order_id",
        )
        .await
        .expect("query");

    assert_eq!(
        pairs(&rows),
        vec![
            (100, "Alice".to_owned()),
            (200, "Bob".to_owned()),
            (300, "Alice".to_owned()),
        ],
        "the join result is correct"
    );

    let report = customers.last_scan().expect("a scan happened");
    assert!(report.substituted, "the join hash supplied the rows");
    assert_eq!(report.used, vec!["jh".to_owned()]);
    assert!(
        report.files_read.is_empty(),
        "no files read — the rows came from the hash"
    );
}

#[tokio::test]
async fn a_join_without_a_hash_falls_back_to_the_table() {
    let customers = Arc::new(customers_table(SnapshotId(810)));
    let orders = Arc::new(orders_table(SnapshotId(810)));
    let session = session();
    session
        .register("orders", Arc::clone(&orders))
        .expect("reg");
    session
        .register("customers", Arc::clone(&customers))
        .expect("reg");

    let rows = session
        .sql(
            "SELECT o.order_id, c.name \
             FROM customers AS c \
             INNER JOIN orders AS o ON c.customer_id = o.customer_id \
             ORDER BY o.order_id",
        )
        .await
        .expect("query");

    assert_eq!(
        pairs(&rows),
        vec![
            (100, "Alice".to_owned()),
            (200, "Bob".to_owned()),
            (300, "Alice".to_owned()),
        ],
        "the join result is still correct without a hash"
    );

    let report = customers.last_scan().expect("a scan happened");
    assert!(!report.substituted, "no hash — the table was read");
}

#[tokio::test]
async fn a_join_reports_the_ask_even_without_a_hash() {
    let customers = Arc::new(customers_table(SnapshotId(810)));
    let orders = Arc::new(orders_table(SnapshotId(810)));
    let session = session();
    session
        .register("orders", Arc::clone(&orders))
        .expect("reg");
    session
        .register("customers", Arc::clone(&customers))
        .expect("reg");

    let _ = session
        .sql(
            "SELECT o.order_id, c.name \
             FROM customers AS c \
             INNER JOIN orders AS o ON c.customer_id = o.customer_id",
        )
        .await
        .expect("query");

    let report = customers.last_scan().expect("a scan happened");
    let ask = report.join.as_ref().expect("join ask reported");
    assert_eq!(ask.table, TableId("customers".into()));
    assert_eq!(ask.keys, std::collections::BTreeSet::from([CUSTOMER_ID]));
    assert_eq!(
        ask.columns,
        std::collections::BTreeSet::from([CUSTOMER_ID, CUSTOMER_NAME])
    );
}

#[tokio::test]
async fn a_right_join_is_not_served_by_a_join_hash() {
    // A right join makes the right side the build side in DataFusion's
    // physical plan, so the left-side hash does not apply.
    let customers = with_hash();
    let orders = Arc::new(orders_table(SnapshotId(810)));
    let session = session();
    session
        .register("orders", Arc::clone(&orders))
        .expect("reg");
    session
        .register("customers", Arc::clone(&customers))
        .expect("reg");

    let _ = session
        .sql(
            "SELECT o.order_id, c.name \
             FROM orders AS o \
             RIGHT JOIN customers AS c ON c.customer_id = o.customer_id",
        )
        .await
        .expect("query");

    // The customers table was the right side, so the join rewrite should
    // not have fired for it. The scan report should show no substitution.
    // (The join ask is also not reported, because the rewrite only
    // recognises inner and left joins.)
    if let Some(report) = customers.last_scan() {
        assert!(
            !report.substituted,
            "right join does not use the left-side hash"
        );
    }
}

//! SQL over a table loaded from an Iceberg REST catalog.
//!
//! The catalog is real: `iceberg-catalog-rest` talking HTTP over a real socket
//! to a mock server that answers `/v1/config` and `loadTable` the way a
//! catalog does. What comes back is a genuine `Table`, and everything below it
//! — manifest lists, manifests, Parquet — is on disk.
//!
//! This is the deployment shape that matters: point at a catalog URI, name a
//! table, query it. The library depends on no catalog implementation, because
//! [`table_from_catalog`] takes the `Table` every catalog hands back.
//!
//! ```sh
//! cargo test --features rest-catalog --test iceberg_rest
//! ```

#![cfg(feature = "rest-catalog")]

use std::collections::{BTreeSet, HashMap};
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use datafusion::arrow::array::{Int64Array, RecordBatch, StringArray};
use datafusion::arrow::datatypes::{DataType, Field, Schema, SchemaRef};
use datafusion::datasource::object_store::ObjectStoreUrl;
use datafusion::parquet::arrow::ArrowWriter;
use iceberg::io::FileIO;
use iceberg::spec::{
    DataContentType, DataFileBuilder, DataFileFormat, ManifestListWriter, ManifestWriterBuilder,
    Struct, TableMetadata,
};
use iceberg::{Catalog, NamespaceIdent, TableIdent};
use iceberg_catalog_rest::{RestCatalog, RestCatalogConfig};
use object_store::local::LocalFileSystem;
use url::Url;

use quarry::derived::{Derived, DerivedId, PolicyFingerprint, Source};
use quarry::engine::{Advertised, Layout, Quarry, Store, hash_scalar, table_from_catalog};
use quarry::from_iceberg::object_path;
use quarry::kinds::Index;
use quarry::registry::Registry;
use quarry::snapshot::{FileId, SnapshotId, TableId};

const TENANT_FIELD: u32 = 1;
const POLICY: PolicyFingerprint = PolicyFingerprint(1);
const TABLE_UUID: &str = "9c12d441-03fe-4693-9a96-a0705ddf69c1";

fn arrow_schema() -> SchemaRef {
    Arc::new(Schema::new(vec![
        Field::new("tenant_id", DataType::Int64, false),
        Field::new("message", DataType::Utf8, false),
    ]))
}

fn scratch(name: &str) -> PathBuf {
    let dir = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(name);
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(dir.join("metadata")).expect("metadata dir");
    fs::create_dir_all(dir.join("data")).expect("data dir");
    dir
}

fn write_parquet(dir: &Path, name: &str, rows: &[(i64, &str)]) -> (String, u64) {
    let path = dir.join("data").join(name);
    let file = fs::File::create(&path).expect("create parquet");
    let mut writer = ArrowWriter::try_new(file, arrow_schema(), None).expect("writer");

    let tenants: Int64Array = rows.iter().map(|(t, _)| *t).collect();
    let messages: StringArray = rows.iter().map(|(_, m)| Some(*m)).collect();
    let batch = RecordBatch::try_new(arrow_schema(), vec![Arc::new(tenants), Arc::new(messages)])
        .expect("batch");
    writer.write(&batch).expect("write");
    writer.close().expect("close");

    let size = fs::metadata(&path).expect("stat").len();
    (path.to_string_lossy().into_owned(), size)
}

fn metadata_json(dir: &Path) -> String {
    let location = dir.to_string_lossy();
    format!(
        r#"{{
            "format-version": 2,
            "table-uuid": "{TABLE_UUID}",
            "location": "{location}",
            "last-sequence-number": 1,
            "last-updated-ms": 1,
            "last-column-id": 2,
            "current-schema-id": 0,
            "schemas": [{{
                "type": "struct",
                "schema-id": 0,
                "fields": [
                    {{"id": 1, "name": "tenant_id", "required": true, "type": "long"}},
                    {{"id": 2, "name": "message", "required": true, "type": "string"}}
                ]
            }}],
            "default-spec-id": 0,
            "partition-specs": [{{"spec-id": 0, "fields": []}}],
            "last-partition-id": 999,
            "default-sort-order-id": 0,
            "sort-orders": [{{"order-id": 0, "fields": []}}],
            "properties": {{}},
            "current-snapshot-id": 1,
            "snapshots": [{{
                "snapshot-id": 1,
                "sequence-number": 1,
                "timestamp-ms": 1,
                "summary": {{"operation": "append"}},
                "manifest-list": "{location}/metadata/list-1.avro",
                "schema-id": 0
            }}],
            "snapshot-log": [],
            "metadata-log": [],
            "refs": {{"main": {{"snapshot-id": 1, "type": "branch"}}}}
        }}"#
    )
}

/// Write a real table on disk and return its metadata JSON and data paths.
async fn table_on_disk(name: &str) -> (PathBuf, String, [String; 3]) {
    let dir = scratch(name);
    let file_io = FileIO::from_path(dir.to_str().expect("utf-8"))
        .expect("file io")
        .build()
        .expect("build file io");

    let (a, a_size) = write_parquet(&dir, "a.parquet", &[(1, "a1"), (1, "a2")]);
    let (b, b_size) = write_parquet(&dir, "b.parquet", &[(2, "b1")]);
    let (c, c_size) = write_parquet(&dir, "c.parquet", &[(1, "c1")]);

    let json = metadata_json(&dir);
    let metadata: TableMetadata = serde_json::from_str(&json).expect("valid metadata");

    let mut writer = ManifestWriterBuilder::new(
        file_io
            .new_output(format!(
                "{}/metadata/manifest-1.avro",
                dir.to_string_lossy()
            ))
            .expect("manifest output"),
        Some(1),
        None,
        metadata.current_schema().clone(),
        metadata.default_partition_spec().as_ref().clone(),
    )
    .build_v2_data();

    for (path, size) in [(&a, a_size), (&b, b_size), (&c, c_size)] {
        writer
            .add_file(
                DataFileBuilder::default()
                    .partition_spec_id(0)
                    .content(DataContentType::Data)
                    .file_path(path.clone())
                    .file_format(DataFileFormat::Parquet)
                    .file_size_in_bytes(size)
                    .record_count(1)
                    .partition(Struct::empty())
                    .build()
                    .expect("data file"),
                1,
            )
            .expect("add file");
    }
    let manifest = writer.write_manifest_file().await.expect("write manifest");

    let mut list = ManifestListWriter::v2(
        file_io
            .new_output(format!("{}/metadata/list-1.avro", dir.to_string_lossy()))
            .expect("list output"),
        1,
        None,
        1,
    );
    list.add_manifests(std::iter::once(manifest))
        .expect("add manifest");
    list.close().await.expect("close list");

    (dir, json, [a, b, c])
}

/// A REST catalog serving one table, over HTTP on a real socket.
///
/// `/v1/config` returns no `warehouse` override on purpose: the client then
/// derives its `FileIO` from the metadata location, which is a local path here.
/// Returning an `s3://` warehouse would send it looking for S3 credentials.
async fn rest_catalog(dir: &Path, metadata: &str) -> (mockito::ServerGuard, RestCatalog) {
    let mut server = mockito::Server::new_async().await;

    server
        .mock("GET", "/v1/config")
        .with_status(200)
        .with_body(r#"{"overrides": {}, "defaults": {}}"#)
        .create_async()
        .await;

    let load_table = format!(
        r#"{{
            "metadata-location": "{}/metadata/v1.metadata.json",
            "metadata": {metadata},
            "config": {{}}
        }}"#,
        dir.to_string_lossy()
    );
    server
        .mock("GET", "/v1/namespaces/db/tables/events")
        .with_status(200)
        .with_body(load_table)
        .create_async()
        .await;

    let catalog = RestCatalog::new(RestCatalogConfig::builder().uri(server.url()).build());
    (server, catalog)
}

fn tenant_index(entries: &[(i64, &str)]) -> Registry {
    let mut index = Index::new(TENANT_FIELD);
    for (tenant, path) in entries {
        index.insert(
            hash_scalar(&datafusion::scalar::ScalarValue::Int64(Some(*tenant))),
            FileId(object_path(path)),
        );
    }
    let mut registry = Registry::new();
    registry.register(Derived::new(
        DerivedId("tenant_idx".into()),
        Source {
            table: TableId(TABLE_UUID.into()),
            snapshot: SnapshotId(1),
        },
        POLICY,
        4096,
        Box::new(index.with_bytes(4096)),
    ));
    registry
}

fn events() -> TableIdent {
    TableIdent::new(NamespaceIdent::new("db".to_owned()), "events".to_owned())
}

fn total_rows(batches: &[RecordBatch]) -> usize {
    batches.iter().map(RecordBatch::num_rows).sum()
}

#[tokio::test]
async fn a_table_loaded_over_rest_is_queryable() {
    let (dir, metadata, _) = table_on_disk("rest_scan").await;
    let (_server, catalog) = rest_catalog(&dir, &metadata).await;

    let loaded = catalog.load_table(&events()).await.expect("load table");
    assert_eq!(loaded.identifier(), &events());

    let table = table_from_catalog(&loaded, ObjectStoreUrl::local_filesystem(), None)
        .await
        .expect("build table");

    let quarry = Quarry::new(
        Url::parse("file://").expect("url"),
        Arc::new(LocalFileSystem::new()),
    );
    let session = quarry.session();
    session
        .register("events", Arc::new(table))
        .expect("register");

    let rows = session
        .sql("SELECT * FROM events ORDER BY message")
        .await
        .expect("query");
    assert_eq!(
        total_rows(&rows),
        4,
        "every row, fetched via a catalog over HTTP"
    );
}

#[tokio::test]
async fn the_rule_prunes_a_table_loaded_over_rest() {
    let (dir, metadata, [a, _b, c]) = table_on_disk("rest_prune").await;
    let (_server, catalog) = rest_catalog(&dir, &metadata).await;

    let loaded = catalog.load_table(&events()).await.expect("load table");
    let table = Arc::new(
        table_from_catalog(&loaded, ObjectStoreUrl::local_filesystem(), None)
            .await
            .expect("build table")
            .with_registry(tenant_index(&[(1, &a), (1, &c)]))
            .with_policy(POLICY),
    );

    let quarry = Quarry::new(
        Url::parse("file://").expect("url"),
        Arc::new(LocalFileSystem::new()),
    );
    let session = quarry.session();
    session
        .register("events", Arc::clone(&table))
        .expect("register");

    let rows = session
        .sql("SELECT * FROM events WHERE tenant_id = 1")
        .await
        .expect("query");
    assert_eq!(total_rows(&rows), 3);

    let report = table.last_scan().expect("a scan happened");
    assert_eq!(report.used.first().map(String::as_str), Some("tenant_idx"));
    assert_eq!(
        report.files_read,
        BTreeSet::from([FileId(object_path(&a)), FileId(object_path(&c))]),
        "the catalog path must prune exactly as the local path does"
    );
}

#[tokio::test]
async fn the_table_identity_survives_the_catalog() {
    // Derived state is keyed on the table's UUID, not the name the catalog
    // happens to serve it under, so state built earlier still matches.
    let (dir, metadata, _) = table_on_disk("rest_identity").await;
    let (_server, catalog) = rest_catalog(&dir, &metadata).await;

    let loaded = catalog.load_table(&events()).await.expect("load table");
    assert_eq!(
        quarry::from_iceberg::table_id(loaded.metadata()).0,
        TABLE_UUID
    );
    assert_eq!(
        quarry::from_iceberg::current_snapshot(loaded.metadata()),
        Some(SnapshotId(1))
    );
}

#[tokio::test]
async fn publish_commits_the_manifest_to_table_metadata() {
    let (dir, metadata, _) = table_on_disk("rest_publish").await;
    let mut server = mockito::Server::new_async().await;

    server
        .mock("GET", "/v1/config")
        .with_status(200)
        .with_body(r#"{"overrides": {}, "defaults": {}}"#)
        .create_async()
        .await;
    let load_table = format!(
        r#"{{"metadata-location": "{}/metadata/v1.metadata.json",
            "metadata": {metadata}, "config": {{}}}}"#,
        dir.to_string_lossy()
    );
    server
        .mock("GET", "/v1/namespaces/db/tables/events")
        .with_status(200)
        .with_body(load_table)
        .create_async()
        .await;
    // The commit: a POST of requirements + updates to the table resource.
    let committed = server
        .mock("POST", "/v1/namespaces/db/tables/events")
        .match_body(mockito::Matcher::Regex(
            "set-statistics.*manifest/1\\.puffin".to_owned(),
        ))
        .with_status(200)
        .with_body(format!(
            r#"{{"metadata-location": "{}/metadata/v2.metadata.json",
                "metadata": {metadata}}}"#,
            dir.to_string_lossy()
        ))
        .create_async()
        .await;

    let catalog = RestCatalog::new(RestCatalogConfig::builder().uri(server.url()).build());
    let loaded = catalog.load_table(&events()).await.expect("load table");

    // Real derived state on disk first, advertised second — the same order as
    // `write`, so a published path never dangles.
    let file_io = Arc::new(
        FileIO::from_path(dir.to_str().expect("utf-8"))
            .expect("file io")
            .build()
            .expect("build file io"),
    );
    let store = Store::new(
        file_io,
        Arc::new(LocalFileSystem::new()),
        Layout::beside(&dir.to_string_lossy()),
    );
    let index_path = store
        .write(&TableId(TABLE_UUID.into()), SnapshotId(1), POLICY, &{
            let mut index = Index::new(TENANT_FIELD);
            index.insert(
                hash_scalar(&datafusion::scalar::ScalarValue::Int64(Some(1))),
                FileId("a.parquet".into()),
            );
            index.with_bytes(128)
        })
        .await
        .expect("write index");

    let stats = store
        .publish(
            &loaded,
            &catalog,
            SnapshotId(1),
            &[Advertised {
                kind: quarry::engine::QUARRY_EQ_INDEX_V2.to_owned(),
                fields: vec![TENANT_FIELD as i32],
                path: index_path.clone(),
                properties: HashMap::new(),
            }],
        )
        .await
        .expect("publish");

    committed.assert_async().await;
    assert_eq!(stats.snapshot_id, 1);
    assert!(
        stats.statistics_path.ends_with("manifest/1.puffin"),
        "published path: {}",
        stats.statistics_path
    );

    // And the advertisement resolves: what the catalog now records points at
    // bytes that recover.
    let recovered = store
        .recover_published(&TableId(TABLE_UUID.into()), &stats, &[SnapshotId(1)])
        .await
        .expect("recover");
    assert_eq!(recovered.registry.len(), 1);
}

//! Full-text search: a `quarry_matches` predicate pruned by an inverted
//! index.
//!
//! Unlike a cube or a top-k, a match is a *filter*, so it is pushed into the
//! scan and needs no plan-level rewrite. These tests go through
//! `Session::sql` anyway, because that is where the predicate function is
//! registered, and they read real Parquet through a metered store so the
//! saving is a measurement rather than a claim about the plan.
//!
//! ```sh
//! cargo test --features engine --test fts
//! ```

#![cfg(feature = "engine")]

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use datafusion::arrow::array::{Int64Array, RecordBatch, StringArray};
use datafusion::arrow::datatypes::{DataType, Field, Schema, SchemaRef};
use datafusion::parquet::arrow::ArrowWriter;
use object_store::local::LocalFileSystem;
use url::Url;

use quarry::derived::{Derived, DerivedId, PolicyFingerprint, Source};
use quarry::engine::{Optimizer, Quarry, QuarryTable, Session, shared, terms, text_index_id};
use quarry::kinds::TextIndex;
use quarry::registry::Registry;
use quarry::snapshot::{FileId, Snapshot, SnapshotGraph, SnapshotId, TableId};
use quarry::workload::Policy;

const ID: u32 = 1;
const BODY: u32 = 2;
const POLICY: PolicyFingerprint = PolicyFingerprint(1);

fn schema() -> SchemaRef {
    Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int64, false),
        Field::new("body", DataType::Utf8, true),
    ]))
}

fn field_ids() -> BTreeMap<String, u32> {
    BTreeMap::from([("id".to_owned(), ID), ("body".to_owned(), BODY)])
}

fn scratch(name: &str) -> PathBuf {
    let dir = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(name);
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("scratch dir");
    dir
}

/// A file whose rows all contain `word`, plus padding shared by every file.
///
/// Padding matters twice: it makes the file big enough that skipping it is
/// worth measuring, and it gives the index a term that prunes *nothing*, so
/// the tests distinguish a real narrowing from an accidental one.
fn write_parquet(dir: &Path, name: &str, first_id: i64, word: &str, rows: usize) -> (FileId, u64) {
    let path = dir.join(name);
    let file = fs::File::create(&path).expect("create parquet");
    let mut writer = ArrowWriter::try_new(file, schema(), None).expect("writer");

    let ids: Int64Array = (0..rows).map(|i| first_id + i as i64).collect();
    let bodies: StringArray = (0..rows)
        .map(|i| {
            Some(format!(
                "{word} shared padding to take up room, line {i} of the log"
            ))
        })
        .collect();
    let batch = RecordBatch::try_new(schema(), vec![Arc::new(ids), Arc::new(bodies)])
        .expect("batch matches schema");
    writer.write(&batch).expect("write");
    writer.close().expect("close");

    let size = fs::metadata(&path).expect("stat").len();
    (FileId(path.to_string_lossy().into_owned()), size)
}

struct Fixture {
    sizes: BTreeMap<FileId, u64>,
    graph: SnapshotGraph,
    files: [FileId; 3],
}

/// Three files, each with a distinguishing word: alpha, beta, gamma.
fn fixture(name: &str) -> Fixture {
    let dir = scratch(name);
    let (a, a_size) = write_parquet(&dir, "a.parquet", 0, "alpha", 400);
    let (b, b_size) = write_parquet(&dir, "b.parquet", 400, "beta", 400);
    let (c, c_size) = write_parquet(&dir, "c.parquet", 800, "gamma", 400);

    let graph = SnapshotGraph::new().with(
        Snapshot::root(SnapshotId(810))
            .with_clean_file(a.clone())
            .with_clean_file(b.clone())
            .with_clean_file(c.clone()),
    );

    Fixture {
        sizes: BTreeMap::from([
            (a.clone(), a_size),
            (b.clone(), b_size),
            (c.clone(), c_size),
        ]),
        graph,
        files: [a, b, c],
    }
}

fn table(fixture: &Fixture, registry: Registry) -> QuarryTable {
    let mut table = QuarryTable::new(
        schema(),
        TableId("logs".into()),
        SnapshotId(810),
        fixture.graph.clone(),
        field_ids(),
    )
    .with_policy(POLICY)
    .on_object_store(
        datafusion::datasource::object_store::ObjectStoreUrl::parse("file://").expect("url"),
    )
    .with_registry(registry);
    for (file, size) in &fixture.sizes {
        table = table.with_parquet_file(file.clone(), *size);
    }
    table
}

/// A metered session over the local filesystem, with the predicate
/// registered.
fn session() -> (Quarry, Session) {
    let quarry = Quarry::new(
        Url::parse("file://").expect("url"),
        Arc::new(LocalFileSystem::new()),
    );
    let session = quarry.session();
    (quarry, session)
}

/// A text index built by hand, so a probe can be tested without a build.
fn text_index(fixture: &Fixture, entries: &[(&str, usize)]) -> Derived {
    let mut index = TextIndex::new(BODY);
    for (word, which) in entries {
        for term in terms(word) {
            index.insert(term, fixture.files[*which].clone());
        }
    }
    let bytes = index.encoded_len();
    Derived::new(
        DerivedId("body_txt".into()),
        Source {
            table: TableId("logs".into()),
            snapshot: SnapshotId(810),
        },
        POLICY,
        bytes,
        Box::new(index.with_bytes(bytes)),
    )
}

fn total_rows(batches: &[RecordBatch]) -> usize {
    batches.iter().map(RecordBatch::num_rows).sum()
}

#[tokio::test]
async fn a_match_prunes_to_the_file_holding_the_term() {
    let fixture = fixture("fts_prune");
    let mut registry = Registry::new();
    // Every file holds "shared"; only b holds "beta".
    registry.register(text_index(
        &fixture,
        &[
            ("alpha", 0),
            ("beta", 1),
            ("gamma", 2),
            ("shared", 0),
            ("shared", 1),
            ("shared", 2),
        ],
    ));
    let table = Arc::new(table(&fixture, registry));

    let (_quarry, session) = session();
    session.register("logs", Arc::clone(&table)).expect("reg");
    let rows = session
        .sql("SELECT id FROM logs WHERE quarry_matches(body, 'beta')")
        .await
        .expect("query");

    assert_eq!(total_rows(&rows), 400, "every row of b matches");
    let report = table.last_scan().expect("a scan happened");
    assert_eq!(
        report.files_read,
        BTreeSet::from([fixture.files[1].clone()]),
        "only the file holding the term is read"
    );
    assert_eq!(report.used, vec!["body_txt".to_owned()]);
}

#[tokio::test]
async fn a_term_every_file_holds_prunes_nothing() {
    // The control for the test above: the same index, a term with postings
    // everywhere, and all three files read. Without this, a pruning result
    // could be an accident of the fixture rather than the index working.
    let fixture = fixture("fts_no_prune");
    let mut registry = Registry::new();
    registry.register(text_index(
        &fixture,
        &[("shared", 0), ("shared", 1), ("shared", 2)],
    ));
    let table = Arc::new(table(&fixture, registry));

    let (_quarry, session) = session();
    session.register("logs", Arc::clone(&table)).expect("reg");
    let rows = session
        .sql("SELECT id FROM logs WHERE quarry_matches(body, 'shared')")
        .await
        .expect("query");

    assert_eq!(total_rows(&rows), 1200, "every row matches");
    assert_eq!(
        table.last_scan().expect("scan").files_read.len(),
        3,
        "nothing to narrow"
    );
}

#[tokio::test]
async fn several_terms_intersect_so_an_impossible_conjunction_reads_nothing() {
    let fixture = fixture("fts_intersect");
    let mut registry = Registry::new();
    registry.register(text_index(&fixture, &[("alpha", 0), ("beta", 1)]));
    let table = Arc::new(table(&fixture, registry));

    let (quarry, session) = session();
    session.register("logs", Arc::clone(&table)).expect("reg");
    let rows = session
        .sql("SELECT id FROM logs WHERE quarry_matches(body, 'alpha beta')")
        .await
        .expect("query");

    assert_eq!(
        total_rows(&rows),
        0,
        "no row holds both words, and the answer says so"
    );
    let report = table.last_scan().expect("scan");
    assert!(
        report.files_read.is_empty(),
        "the intersection is empty, so no file can match: {:?}",
        report.files_read
    );
    assert_eq!(
        quarry.origin_stats().bytes_fetched,
        0,
        "and provably nothing was fetched"
    );
}

#[tokio::test]
async fn the_answer_matches_the_unaided_query() {
    // The property that matters: pruning must not change the answer.
    let fixture = fixture("fts_same_answer");
    let mut registry = Registry::new();
    registry.register(text_index(
        &fixture,
        &[("alpha", 0), ("beta", 1), ("gamma", 2)],
    ));
    let served = Arc::new(table(&fixture, registry));
    let unaided = Arc::new(table(&fixture, Registry::new()));

    let sql = "SELECT count(*) AS n FROM logs WHERE quarry_matches(body, 'gamma')";

    let (_q1, one) = session();
    one.register("logs", Arc::clone(&served)).expect("reg");
    let with = one.sql(sql).await.expect("query");

    let (_q2, other) = session();
    other.register("logs", Arc::clone(&unaided)).expect("reg");
    let without = other.sql(sql).await.expect("query");

    assert_eq!(format!("{with:?}"), format!("{without:?}"));
    assert_eq!(served.last_scan().expect("scan").files_read.len(), 1);
    assert_eq!(unaided.last_scan().expect("scan").files_read.len(), 3);
}

#[tokio::test]
async fn a_prefix_is_not_a_term() {
    // `quarry_matches` is not a LIKE. The index cannot answer a substring,
    // so the predicate must not claim to either — and the rows returned are
    // what proves it, not the plan.
    let fixture = fixture("fts_prefix");
    let table = Arc::new(table(&fixture, Registry::new()));

    let (_quarry, session) = session();
    session.register("logs", Arc::clone(&table)).expect("reg");
    let rows = session
        .sql("SELECT id FROM logs WHERE quarry_matches(body, 'alph')")
        .await
        .expect("query");

    assert_eq!(total_rows(&rows), 0, "'alph' is not the word 'alpha'");
}

#[tokio::test]
async fn matching_ignores_case_and_punctuation() {
    let fixture = fixture("fts_case");
    let table = Arc::new(table(&fixture, Registry::new()));

    let (_quarry, session) = session();
    session.register("logs", Arc::clone(&table)).expect("reg");
    let rows = session
        .sql("SELECT id FROM logs WHERE quarry_matches(body, 'ALPHA!')")
        .await
        .expect("query");

    assert_eq!(total_rows(&rows), 400);
}

#[tokio::test]
async fn a_stale_index_reads_the_files_added_since() {
    // The pruning staleness rule, for this kind: an index that has never
    // seen a file must not cause its rows to be missed.
    let mut fixture = fixture("fts_stale");
    let mut registry = Registry::new();
    registry.register(text_index(&fixture, &[("alpha", 0)]));

    // A fourth file, holding "alpha" too, committed after the index was built.
    let dir = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("fts_stale");
    let (d, d_size) = write_parquet(&dir, "d.parquet", 1200, "alpha", 100);
    fixture.sizes.insert(d.clone(), d_size);
    let mut next = Snapshot::child_of(SnapshotId(811), SnapshotId(810));
    for file in fixture.sizes.keys() {
        next = next.with_clean_file(file.clone());
    }
    fixture.graph.insert(next);

    let mut table = QuarryTable::new(
        schema(),
        TableId("logs".into()),
        SnapshotId(811),
        fixture.graph.clone(),
        field_ids(),
    )
    .with_policy(POLICY)
    .on_object_store(
        datafusion::datasource::object_store::ObjectStoreUrl::parse("file://").expect("url"),
    )
    .with_registry(registry);
    for (file, size) in &fixture.sizes {
        table = table.with_parquet_file(file.clone(), *size);
    }
    let table = Arc::new(table);

    let (_quarry, session) = session();
    session.register("logs", Arc::clone(&table)).expect("reg");
    let rows = session
        .sql("SELECT id FROM logs WHERE quarry_matches(body, 'alpha')")
        .await
        .expect("query");

    assert_eq!(
        total_rows(&rows),
        500,
        "400 from the indexed file and 100 from the one it never saw"
    );
    let report = table.last_scan().expect("scan");
    assert!(report.also_scanned.contains(&d), "d was unioned back in");
}

#[tokio::test]
async fn repeated_matches_make_the_optimizer_build_the_index() {
    let fixture = fixture("fts_loop");
    let registry = shared(Registry::new());
    let table =
        Arc::new(table(&fixture, Registry::new()).with_shared_registry(Arc::clone(&registry)));

    let (_quarry, session) = session();
    session.register("logs", Arc::clone(&table)).expect("reg");

    let mut optimizer = Optimizer::new(
        Arc::clone(&registry),
        Policy::automatic(1_000_000_000).with_min_queries(2),
    )
    .for_reader(POLICY);

    let sql = "SELECT id FROM logs WHERE quarry_matches(body, 'beta')";
    for _ in 0..2 {
        session.sql(sql).await.expect("query");
        let report = table.last_scan().expect("scan");
        assert!(report.used.is_empty(), "nothing to serve it yet");
        optimizer.observe(report.observation(report.bytes_planned(&fixture.sizes)));
    }

    let round = optimizer.build_recommended(&session, &table).await;
    assert!(
        round
            .built
            .contains(&text_index_id(&TableId("logs".into()), BODY)),
        "the repeated match earned a text index: {round:?}"
    );

    // And it prunes on the next query, with the same answer.
    let rows = session.sql(sql).await.expect("query");
    assert_eq!(total_rows(&rows), 400);
    let report = table.last_scan().expect("scan");
    assert_eq!(
        report.files_read,
        BTreeSet::from([fixture.files[1].clone()]),
        "the built index narrowed the scan to b"
    );
}

#[tokio::test]
async fn a_repeated_match_does_not_earn_an_equality_index() {
    // A match is not an equality, and a scalar index could never serve one.
    // Keeping matches out of `Fingerprint::probeable` is what prevents the
    // optimizer from spending a build learning that.
    let fixture = fixture("fts_not_equality");
    let registry = shared(Registry::new());
    let table =
        Arc::new(table(&fixture, Registry::new()).with_shared_registry(Arc::clone(&registry)));

    let (_quarry, session) = session();
    session.register("logs", Arc::clone(&table)).expect("reg");

    let mut optimizer = Optimizer::new(
        Arc::clone(&registry),
        Policy::automatic(1_000_000_000).with_min_queries(2),
    )
    .for_reader(POLICY);

    for _ in 0..3 {
        session
            .sql("SELECT id FROM logs WHERE quarry_matches(body, 'beta')")
            .await
            .expect("query");
        let report = table.last_scan().expect("scan");
        optimizer.observe(report.observation(report.bytes_planned(&fixture.sizes)));
    }

    assert!(
        optimizer.proposals().is_empty(),
        "no equality-index proposal: {:?}",
        optimizer.proposals()
    );
}

//! Aggregate queries served from a cube — the plan-level half of the rule.
//!
//! A scan never sees a group-by, so all of this goes through `Session::sql`:
//! the aggregate is recognised in the logical plan, the registry decides
//! whether a cube may serve it, and the stored partials are re-aggregated at
//! the query's grain.
//!
//! ```sh
//! cargo test --features engine --test cube
//! ```

#![cfg(feature = "engine")]

use std::collections::{BTreeMap, BTreeSet};
use std::sync::Arc;

use datafusion::arrow::array::{Int64Array, RecordBatch};
use datafusion::arrow::datatypes::{DataType, Field, Schema, SchemaRef};
use url::Url;

use quarry::derived::{
    AggFunc, Aggregate, Derived, DerivedId, Measure, Plan, PolicyFingerprint, Source,
};
use quarry::engine::{MaterializedResult, Quarry, QuarryTable, Rollup, Session};
use quarry::registry::Registry;
use quarry::snapshot::{FileId, Snapshot, SnapshotGraph, SnapshotId, TableId};

const DAY: u32 = 1;
const BYTES: u32 = 3;
const TENANT: u32 = 4;
const POLICY: PolicyFingerprint = PolicyFingerprint(1);

fn schema() -> SchemaRef {
    Arc::new(Schema::new(vec![
        Field::new("day", DataType::Int64, false),
        Field::new("bytes", DataType::Int64, false),
        Field::new("tenant_id", DataType::Int64, false),
    ]))
}

fn field_ids() -> BTreeMap<String, u32> {
    BTreeMap::from([
        ("day".to_owned(), DAY),
        ("bytes".to_owned(), BYTES),
        ("tenant_id".to_owned(), TENANT),
    ])
}

/// The base rows: six events across two days and two tenants.
fn batch() -> RecordBatch {
    RecordBatch::try_new(
        schema(),
        vec![
            Arc::new(Int64Array::from(vec![1i64, 1, 1, 2, 2, 2])),
            Arc::new(Int64Array::from(vec![10i64, 20, 30, 40, 50, 60])),
            Arc::new(Int64Array::from(vec![1i64, 1, 2, 1, 2, 2])),
        ],
    )
    .expect("batch")
}

fn table(at: SnapshotId) -> QuarryTable {
    QuarryTable::new(
        schema(),
        TableId("events".into()),
        at,
        SnapshotGraph::new().with(Snapshot::root(at).with_clean_file(FileId("a".into()))),
        field_ids(),
    )
    .with_policy(POLICY)
    .with_file(FileId("a".into()), vec![batch()])
}

fn count_star() -> Measure {
    Measure {
        func: AggFunc::Count,
        field: None,
    }
}

fn sum_bytes() -> Measure {
    Measure {
        func: AggFunc::Sum,
        field: Some(BYTES),
    }
}

/// The cube's grain and stored column names.
fn rollup() -> Rollup {
    Rollup::new(
        Aggregate {
            group_by: BTreeSet::from([DAY, TENANT]),
            measures: BTreeSet::from([count_star(), sum_bytes()]),
        },
        BTreeMap::from([
            (DAY, "day".to_owned()),
            (TENANT, "tenant_id".to_owned()),
            (BYTES, "bytes".to_owned()),
        ]),
    )
}

/// Partials at the cube's grain, in `Rollup::columns` order.
fn cube_rows() -> Vec<RecordBatch> {
    let schema = Arc::new(Schema::new(vec![
        Field::new("day", DataType::Int64, false),
        Field::new("tenant_id", DataType::Int64, false),
        Field::new("count(*)", DataType::Int64, false),
        Field::new("sum(bytes)", DataType::Int64, false),
    ]));
    vec![
        RecordBatch::try_new(
            Arc::clone(&schema),
            vec![
                Arc::new(Int64Array::from(vec![1i64, 1, 2, 2])),
                Arc::new(Int64Array::from(vec![1i64, 2, 1, 2])),
                Arc::new(Int64Array::from(vec![2i64, 1, 1, 2])),
                Arc::new(Int64Array::from(vec![30i64, 30, 40, 110])),
            ],
        )
        .expect("cube"),
    ]
}

fn build_plan() -> Plan {
    // The cube was built over the whole table: no filters baked in.
    Plan::new(BTreeSet::from([DAY, BYTES, TENANT]), Vec::<String>::new())
}

fn with_cube(at: SnapshotId) -> Arc<QuarryTable> {
    let id = DerivedId("cube".into());
    let mut registry = Registry::new();
    registry.register(Derived::new(
        id.clone(),
        Source {
            table: TableId("events".into()),
            snapshot: at,
        },
        POLICY,
        128,
        Box::new(MaterializedResult::aggregate_of(
            build_plan(),
            rollup(),
            cube_rows(),
        )),
    ));
    Arc::new(
        table(at)
            .with_registry(registry)
            .with_cube(id, &rollup(), cube_rows()),
    )
}

fn session() -> Session {
    Quarry::new(
        Url::parse("memory://").expect("url"),
        Arc::new(object_store::memory::InMemory::new()),
    )
    .session()
}

/// (day, sum) pairs out of a result, whatever order they came back in.
fn pairs(rows: &[RecordBatch]) -> BTreeMap<i64, i64> {
    let mut out = BTreeMap::new();
    for batch in rows {
        let keys = batch
            .column(0)
            .as_any()
            .downcast_ref::<Int64Array>()
            .expect("i64 keys");
        let values = batch
            .column(1)
            .as_any()
            .downcast_ref::<Int64Array>()
            .expect("i64 values");
        for i in 0..batch.num_rows() {
            out.insert(keys.value(i), values.value(i));
        }
    }
    out
}

#[tokio::test]
async fn a_cube_serves_the_grain_it_was_built_at() {
    let table = with_cube(SnapshotId(810));
    let session = session();
    session.register("events", Arc::clone(&table)).expect("reg");

    let rows = session
        .sql("SELECT day, tenant_id, count(*), sum(bytes) FROM events GROUP BY day, tenant_id")
        .await
        .expect("sql");
    assert_eq!(rows.iter().map(|b| b.num_rows()).sum::<usize>(), 4);
    assert_eq!(table.last_scan().expect("report").used, ["cube"]);
    assert!(table.last_scan().expect("report").substituted);
}

