    );

    let report = table.last_scan().expect("a scan happened");
    assert!(
        !report.files_read.contains(&file("a")),
        "read {:?}, which includes a file the table no longer references",
        report.files_read
    );
    assert_eq!(report.files_read, BTreeSet::from([file("merged")]));
