    )]));
    let wrong = RecordBatch::try_new(
        wrong_schema,
        vec![Arc::new(StringArray::from(vec!["not-an-int"]))],
    )
    .expect("batch matches its own schema");

    table_with_three_files(graph, SnapshotId(810))
        .with_materialized(DerivedId("bad".into()), vec![wrong]);
}

