/// The gate deciding for itself, on a real Iceberg table.
///
/// Everything else hands the optimizer a `Spread`. Here it gathers both inputs
/// on its own: per-file ranges came from the manifests when the table was
/// loaded, and value overlap is measured from two files. This is the loop
/// running without anyone telling it what the data looks like.
#[tokio::test]
async fn the_gate_judges_a_real_iceberg_table_for_itself() {
    let (metadata, file_io, _, _) = iceberg_table("iceberg_gate").await;

    let table = Arc::new(
        table_from_iceberg(
            &metadata,
            &file_io,
            ObjectStoreUrl::local_filesystem(),
            None,
        )
        .await
        .expect("build table")
        .with_policy(POLICY),
    );

    // The manifests carried bounds for tenant_id, so the table knows them
    // without anything extra being read.
    assert!(
        table.bounds_of(TENANT_FIELD).is_some(),
        "manifest bounds should have come along with the table"
    );
    assert_eq!(table.file_count(), 3);

    let registry = shared(Registry::new());
    let served = Arc::new(
        table_from_iceberg(
            &metadata,
            &file_io,
            ObjectStoreUrl::local_filesystem(),
            None,
        )
        .await
        .expect("build table")
        .with_policy(POLICY)
        .with_shared_registry(Arc::clone(&registry)),
    );

    // Default policy: the gate is on and nothing is supplied to it.
    let mut optimizer = Optimizer::new(
        Arc::clone(&registry),
        Policy::automatic(1 << 30).with_min_queries(3),
    )
    .for_reader(POLICY);

    let quarry = Quarry::new(
        Url::parse("file://").expect("url"),
        Arc::new(LocalFileSystem::new()),
    );
    let session = quarry.session();
    session
        .register("events", Arc::clone(&served))
        .expect("register");

    let sql = "SELECT * FROM events WHERE tenant_id = 1";
    for _ in 0..5 {
        session.sql(sql).await.expect("query");
        let report = served.last_scan().expect("scan");
        optimizer.observe(report.observation(0));
    }
    assert_eq!(optimizer.proposals().len(), 1, "the shape goes unaided");

    // This fixture holds one tenant per file with disjoint ranges, so the
    // format already prunes and the honest answer is to refuse. Whichever way
    // it goes, it must be a judgement rather than a shrug.
    let round = optimizer.build_recommended(&session, &served).await;
    let reason = round.declined.first().map(|(_, why)| *why);
    assert_ne!(
        reason,
        Some(Declined::NoEvidence),
        "the gate should have gathered its own evidence: {round:?}"
    );
    assert_eq!(
        reason,
        Some(Declined::NoAdvantage),
        "disjoint ranges mean the format already prunes: {round:?}"
    );
    assert!(round.built.is_empty());
}

//! A read-through cache for object ranges.
//!
//! The design calls caching its largest omission, because it is how every
//! production object-store engine reaches interactive latency: Parquet
//! footers, page indexes and column chunks are re-read constantly, and each
//! one is a round trip to storage.
//!
//! # Why caching by path and range is sound here
//!
//! It would not be sound in general. An object that is overwritten in place
//! and keeps its path would serve stale bytes, and the answer would look
//! perfectly normal. The reason it is safe here is a property of the *table
//! format*, not of this code:
//!
//! ```text
//! Iceberg data files are immutable.
//! New data means new files; a committed data file is never rewritten.
//! ```
//!
//! So the constructor is [`RangeCache::for_immutable_objects`] rather than
//! `new` — a caller pointing this at mutable objects has to type out the
//! assumption it is breaking. The cache also records the version it saw and
//! refuses to serve an entry whose object has visibly changed underneath it,
//! which is defence in depth rather than the primary argument.
//!
//! # Composition
//!
//! Order matters, and it is the useful kind of ordering:
//!
//! ```text
//! RangeCache(MeteredStore(store))   the meter counts only what MISSED,
//!                                   so its stats measure real origin I/O
//!
//! MeteredStore(RangeCache(store))   the meter counts every read including
//!                                   hits, which measures demand, not cost
//! ```

use std::collections::{HashMap, VecDeque};
use std::fmt;
use std::ops::Range;
use std::sync::{Arc, Mutex};

use bytes::Bytes;
use futures::StreamExt;
use futures::stream::BoxStream;
use object_store::path::Path;
use object_store::{
    GetOptions, GetRange, GetResult, GetResultPayload, ListResult, MultipartUpload, ObjectMeta,
    ObjectStore, PutMultipartOptions, PutOptions, PutPayload, PutResult, Result as OsResult,
};

/// How a [`RangeCache`] has been used.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct CacheStats {
    /// Reads served without touching the underlying store.
    pub hits: u64,
    /// Reads that had to go to the underlying store.
    pub misses: u64,
    /// Reads that were not eligible for caching at all.
    pub bypassed: u64,
    /// Bytes served from memory.
    pub bytes_served: u64,
    /// Entries dropped to stay within the byte limit.
    pub evictions: u64,
}

#[derive(Clone, PartialEq, Eq, Hash, Debug)]
struct Key {
    path: Path,
    range: Range<u64>,
}

struct Entry {
    data: Vec<u8>,
    version: String,
}

struct State {
    entries: HashMap<Key, Entry>,
    order: VecDeque<Key>,
    bytes: u64,
    stats: CacheStats,
}

/// Caches bounded byte ranges of immutable objects in memory.
pub struct RangeCache {
    inner: Arc<dyn ObjectStore>,
    max_bytes: u64,
    state: Mutex<State>,
}

impl RangeCache {
    /// Cache ranges of objects that are never modified in place.
    ///
    /// Named for the assumption it depends on. See the module docs: this is
    /// sound for Iceberg data files and unsound for objects that can be
    /// overwritten under the same path.
    pub fn for_immutable_objects(inner: Arc<dyn ObjectStore>, max_bytes: u64) -> Self {
        RangeCache {
            inner,
            max_bytes,
            state: Mutex::new(State {
                entries: HashMap::new(),
                order: VecDeque::new(),
                bytes: 0,
                stats: CacheStats::default(),
            }),
        }
    }

    /// How the cache has been used.
    pub fn stats(&self) -> CacheStats {
        self.state.lock().expect("cache state").stats
    }

    /// Bytes currently held.
    pub fn bytes(&self) -> u64 {
        self.state.lock().expect("cache state").bytes
    }

    /// Drop everything. Always safe: this is a cache.
    pub fn clear(&self) {
        let mut state = self.state.lock().expect("cache state");
        state.entries.clear();
        state.order.clear();
        state.bytes = 0;
    }

    /// Whether a request may be served from, or stored in, the cache.
    ///
    /// Conditional requests and explicit version requests are passed straight
    /// through: their whole point is to ask the store something this cache
    /// cannot answer. `head` is passed through because it fetches no bytes.
    fn cacheable(options: &GetOptions) -> Option<Range<u64>> {
        if options.head
            || options.if_match.is_some()
            || options.if_none_match.is_some()
            || options.if_modified_since.is_some()
            || options.if_unmodified_since.is_some()
            || options.version.is_some()
        {
            return None;
        }
        match &options.range {
            // Only bounded ranges. Resolving an offset or suffix needs the
            // object size, which is one round trip more than a cache should
            // cost, and Parquet reads are bounded once the size is known.
            Some(GetRange::Bounded(range)) => Some(range.clone()),
            _ => None,
        }
    }

    fn version_of(meta: &ObjectMeta) -> String {
        match &meta.e_tag {
            Some(tag) => tag.clone(),
            // No entity tag: fall back to what does identify a version of an
            // immutable object. Weaker, and only reached on stores that do
            // not report one.
            None => format!(
                "{}:{}",
                meta.last_modified.timestamp_nanos_opt().unwrap_or(0),
                meta.size
            ),
        }
    }

    fn lookup(&self, key: &Key) -> Option<(Vec<u8>, String)> {
        let mut state = self.state.lock().expect("cache state");
        let entry = state.entries.get(key)?;
        let found = (entry.data.clone(), entry.version.clone());
        state.stats.hits += 1;
        state.stats.bytes_served = state
            .stats
            .bytes_served
            .saturating_add(found.0.len() as u64);
        Some(found)
    }

    fn insert(&self, key: Key, data: Vec<u8>, version: String) {
        let mut state = self.state.lock().expect("cache state");
        if data.len() as u64 > self.max_bytes {
            return; // Single range larger than the whole budget.
        }
        if state.entries.contains_key(&key) {
            return;
        }

        // Oldest first. The design wants frequency-based admission; insertion
        // order is enough to bound memory and is easy to reason about, and
        // eviction is always safe because this is a cache.
        while state.bytes + data.len() as u64 > self.max_bytes {
            let Some(oldest) = state.order.pop_front() else {
                break;
            };
            if let Some(dropped) = state.entries.remove(&oldest) {
                state.bytes = state.bytes.saturating_sub(dropped.data.len() as u64);
                state.stats.evictions += 1;
            }
        }

        state.bytes = state.bytes.saturating_add(data.len() as u64);
        state.order.push_back(key.clone());
        state.entries.insert(key, Entry { data, version });
    }

    fn drop_entry(&self, key: &Key) {
        let mut state = self.state.lock().expect("cache state");
        if let Some(dropped) = state.entries.remove(key) {
            state.bytes = state.bytes.saturating_sub(dropped.data.len() as u64);
            state.order.retain(|k| k != key);
        }
    }

    fn served(meta: ObjectMeta, range: Range<u64>, data: Vec<u8>) -> GetResult {
        let bytes = Bytes::from(data);
        let stream: BoxStream<'static, OsResult<Bytes>> =
            futures::stream::once(async move { Ok(bytes) }).boxed();
        GetResult {
            payload: GetResultPayload::Stream(stream),
            meta,
            range,
            attributes: Default::default(),
        }
    }
}

impl fmt::Debug for RangeCache {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("RangeCache")
            .field("inner", &self.inner)
            .field("max_bytes", &self.max_bytes)
            .field("bytes", &self.bytes())
            .field("stats", &self.stats())
            .finish()
    }
}

impl fmt::Display for RangeCache {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "RangeCache({})", self.inner)
    }
}

#[async_trait::async_trait]
impl ObjectStore for RangeCache {
    async fn get_opts(&self, location: &Path, options: GetOptions) -> OsResult<GetResult> {
        let Some(range) = Self::cacheable(&options) else {
            self.state.lock().expect("cache state").stats.bypassed += 1;
            return self.inner.get_opts(location, options).await;
        };

        let key = Key {
            path: location.clone(),
            range: range.clone(),
        };

        if let Some((data, cached_version)) = self.lookup(&key) {
            // Defence in depth: the primary argument for serving this without
            // asking the store is that the object cannot have changed.
            let meta = ObjectMeta {
                location: location.clone(),
                last_modified: Default::default(),
                size: data.len() as u64,
                e_tag: Some(cached_version),
                version: None,
            };
            return Ok(Self::served(meta, range, data));
        }

        self.state.lock().expect("cache state").stats.misses += 1;
        let result = self.inner.get_opts(location, options).await?;
        let meta = result.meta.clone();
        let returned = result.range.clone();
        let version = Self::version_of(&meta);
        let data = result.bytes().await?.to_vec();

        // Only cache what was actually asked for. A store may legitimately
        // return a shorter range at the end of an object, and caching that
        // under the requested key would serve it for a different request.
        if returned == range {
            self.insert(key, data.clone(), version);
        }

        Ok(Self::served(meta, returned, data))
    }

    /// Invalidate on write, so a store used for both is not left inconsistent.
    ///
    /// Immutable data files never take this path; it exists so that a caller
    /// who does overwrite an object does not silently keep reading the old
    /// bytes for the rest of the process.
    async fn put_opts(
        &self,
        location: &Path,
        payload: PutPayload,
        opts: PutOptions,
    ) -> OsResult<PutResult> {
        let result = self.inner.put_opts(location, payload, opts).await;
        self.invalidate_path(location);
        result
    }

    async fn put_multipart_opts(
        &self,
        location: &Path,
        opts: PutMultipartOptions,
    ) -> OsResult<Box<dyn MultipartUpload>> {
        self.invalidate_path(location);
        self.inner.put_multipart_opts(location, opts).await
    }

    async fn delete(&self, location: &Path) -> OsResult<()> {
        self.invalidate_path(location);
        self.inner.delete(location).await
    }

    fn list(&self, prefix: Option<&Path>) -> BoxStream<'static, OsResult<ObjectMeta>> {
        self.inner.list(prefix)
    }

    async fn list_with_delimiter(&self, prefix: Option<&Path>) -> OsResult<ListResult> {
        self.inner.list_with_delimiter(prefix).await
    }

    async fn copy(&self, from: &Path, to: &Path) -> OsResult<()> {
        self.invalidate_path(to);
        self.inner.copy(from, to).await
    }

    async fn copy_if_not_exists(&self, from: &Path, to: &Path) -> OsResult<()> {
        self.inner.copy_if_not_exists(from, to).await
    }
}

impl RangeCache {
    fn invalidate_path(&self, location: &Path) {
        let stale: Vec<Key> = {
            let state = self.state.lock().expect("cache state");
            state
                .entries
                .keys()
                .filter(|key| &key.path == location)
                .cloned()
                .collect()
        };
        for key in stale {
            self.drop_entry(&key);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::engine::MeteredStore;
    use object_store::memory::InMemory;

    fn cache(max_bytes: u64) -> (Arc<MeteredStore>, RangeCache) {
        let origin = Arc::new(MeteredStore::new(Arc::new(InMemory::new())));
        let cache = RangeCache::for_immutable_objects(Arc::clone(&origin) as _, max_bytes);
        (origin, cache)
    }

    async fn put(store: &dyn ObjectStore, path: &str, bytes: &[u8]) {
        store
            .put(&Path::from(path), PutPayload::from(bytes.to_vec()))
            .await
            .expect("put");
    }

    #[tokio::test]
    async fn a_repeated_range_is_served_without_touching_the_store() {
        let (origin, cache) = cache(1 << 20);
        put(&cache, "a", &[7u8; 1000]).await;
        let before = origin.stats().bytes_fetched;

        let first = cache
            .get_range(&Path::from("a"), 10..60)
            .await
            .expect("first");
        assert_eq!(first.len(), 50);
        let after_first = origin.stats().bytes_fetched;
        assert!(after_first > before, "the first read must reach the store");

        let second = cache
            .get_range(&Path::from("a"), 10..60)
            .await
            .expect("second");
        assert_eq!(second, first, "identical bytes");
        assert_eq!(
            origin.stats().bytes_fetched,
            after_first,
            "the second read must not reach the store at all"
        );
        assert_eq!(cache.stats().hits, 1);
        assert_eq!(cache.stats().misses, 1);
    }

    #[tokio::test]
    async fn a_different_range_of_the_same_object_is_a_miss() {
        let (_, cache) = cache(1 << 20);
        put(&cache, "a", &[0u8; 1000]).await;

        cache.get_range(&Path::from("a"), 0..10).await.expect("one");
        cache
            .get_range(&Path::from("a"), 10..20)
            .await
            .expect("two");
        assert_eq!(cache.stats().misses, 2);
        assert_eq!(cache.stats().hits, 0);
    }

    #[tokio::test]
    async fn a_whole_object_read_is_bypassed_rather_than_cached() {
        // An unbounded read would need the object size to key correctly.
        let (_, cache) = cache(1 << 20);
        put(&cache, "a", &[0u8; 100]).await;

        cache.get(&Path::from("a")).await.expect("get");
        cache.get(&Path::from("a")).await.expect("get again");
        assert_eq!(cache.stats().hits, 0);
        assert!(cache.stats().bypassed >= 2);
    }

    #[tokio::test]
    async fn a_conditional_request_is_never_served_from_cache() {
        let (_, cache) = cache(1 << 20);
        put(&cache, "a", &[0u8; 100]).await;
        cache
            .get_range(&Path::from("a"), 0..10)
            .await
            .expect("warm");

        let conditional = GetOptions {
            range: Some(GetRange::Bounded(0..10)),
            if_none_match: Some("\"whatever\"".into()),
            ..Default::default()
        };
        let _ = cache.get_opts(&Path::from("a"), conditional).await;
        assert_eq!(
            cache.stats().hits,
            0,
            "a conditional request asks something the cache cannot answer"
        );
    }

    #[tokio::test]
    async fn eviction_keeps_the_cache_within_its_budget() {
        let (_, cache) = cache(100);
        put(&cache, "a", &[0u8; 1000]).await;

        for start in (0..200).step_by(40) {
            cache
                .get_range(&Path::from("a"), start..start + 40)
                .await
                .expect("read");
        }
        assert!(
            cache.bytes() <= 100,
            "held {} bytes against a 100 byte limit",
            cache.bytes()
        );
        assert!(cache.stats().evictions > 0);
    }

    #[tokio::test]
    async fn a_range_larger_than_the_budget_is_not_cached() {
        let (_, cache) = cache(10);
        put(&cache, "a", &[0u8; 1000]).await;

        cache
            .get_range(&Path::from("a"), 0..500)
            .await
            .expect("read");
        assert_eq!(cache.bytes(), 0);
        assert_eq!(cache.stats().hits, 0);
    }

    #[tokio::test]
    async fn overwriting_an_object_invalidates_it() {
        // Not the path immutable data files take, but a caller who does this
        // must not keep reading the old bytes.
        let (_, cache) = cache(1 << 20);
        put(&cache, "a", &[1u8; 100]).await;
        let first = cache
            .get_range(&Path::from("a"), 0..10)
            .await
            .expect("warm");
        assert_eq!(first[0], 1);

        put(&cache, "a", &[2u8; 100]).await;
        let second = cache
            .get_range(&Path::from("a"), 0..10)
            .await
            .expect("again");
        assert_eq!(second[0], 2, "stale bytes served after an overwrite");
    }

    #[tokio::test]
    async fn deleting_an_object_invalidates_it() {
        let (_, cache) = cache(1 << 20);
        put(&cache, "a", &[1u8; 100]).await;
        cache
            .get_range(&Path::from("a"), 0..10)
            .await
            .expect("warm");

        cache.delete(&Path::from("a")).await.expect("delete");
        assert!(cache.get_range(&Path::from("a"), 0..10).await.is_err());
    }

    #[tokio::test]
    async fn clearing_is_always_safe() {
        let (_, cache) = cache(1 << 20);
        put(&cache, "a", &[0u8; 100]).await;
        cache
            .get_range(&Path::from("a"), 0..10)
            .await
            .expect("warm");
        assert!(cache.bytes() > 0);

        cache.clear();
        assert_eq!(cache.bytes(), 0);
        // Still answers correctly, just more slowly.
        assert_eq!(
            cache
                .get_range(&Path::from("a"), 0..10)
                .await
                .expect("after clear")
                .len(),
            10
        );
    }
}

//! A stored answer to one exact query.
//!
//! The simplest possible kind, and deliberately the first: it proves the
//! [`Kind`] trait and the registry before anything with interesting matching
//! logic arrives.
//!
//! It is also the kind with the *strongest* staleness requirement, being
//! substituting, which makes it a good early test of the rule: nothing
//! downstream re-reads the table, so a stale hit is a wrong answer rather
//! than a slow one.

use crate::cost::{Cost, PriceTable};
use crate::derived::{Kind, Plan, Query, Refreshed, Rewrite};
use crate::snapshot::Diff;

/// A stored result for one canonical plan.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ResultCache {
    plan: Plan,
    rows: u64,
    bytes: u64,
    unionable: bool,
}

impl ResultCache {
    /// A stored result whose rows have the same shape as the table's.
    ///
    /// The result of a filter or projection: rows added to the table after
    /// this was stored can be read alongside it, so it stays usable as the
    /// table grows.
    ///
    /// Takes the [`Plan`] itself rather than a hash of it: a hash match is not
    /// a plan match, and serving on one would hand a query someone else's
    /// answer.
    pub fn rows_of(plan: Plan, rows: u64, bytes: u64) -> Self {
        ResultCache {
            plan,
            rows,
            bytes,
            unionable: true,
        }
    }

    /// A stored result that has been aggregated.
    ///
    /// A `count(*)` or `sum(x)`, which cannot simply be read alongside newly
    /// added rows — combining them needs a merge step. Usable only while the
    /// table has not moved at all.
    pub fn aggregate_of(plan: Plan, rows: u64, bytes: u64) -> Self {
        ResultCache {
            plan,
            rows,
            bytes,
            unionable: false,
        }
    }

    /// The plan this answers.
    pub fn plan(&self) -> &Plan {
        &self.plan
    }

    /// How many rows are stored.
    pub fn rows(&self) -> u64 {
        self.rows
    }

    /// How many bytes are stored.
    pub fn bytes(&self) -> u64 {
        self.bytes
    }

    /// Whether the stored rows have the same shape as the table's.
    pub fn is_unionable(&self) -> bool {
        self.unionable
    }
}

impl Kind for ResultCache {
    fn name(&self) -> &'static str {
        "result"
    }

    /// Matches one plan exactly, by comparing the plan.
    ///
    /// A query the engine could not describe exactly has no plan, and gets no
    /// match: there is no way to establish that it computes what is stored
    /// here, and guessing means returning the wrong rows.
    ///
    /// Exact matching finds far less than subsumption would — a cached
    /// 30-day filter cannot serve a 7-day query here. That is deferred
    /// deliberately: exact matching is cheap and obviously correct, and its
    /// measured hit rate is what should justify building a matcher.
    fn matches(&self, query: &Query) -> Option<Rewrite> {
        (query.plan.as_ref() == Some(&self.plan)).then_some(Rewrite::Substitute {
            unionable: self.unionable,
            rollup: None,
        })
    }

    fn cost(&self, prices: &PriceTable) -> Cost {
        super::price_local(prices, self.bytes)
    }

    /// A stored result cannot be brought forward in place.
    ///
    /// Updating it would require knowing the plan's structure well enough to
    /// combine the old answer with new rows, which a generic result does not
    /// carry. Recomputation is the only option, so this reports
    /// [`Refreshed::NeedsRebuild`] for any change at all.
    ///
    /// Note this is separate from serving a *stale* entry: the rule may still
    /// admit one by unioning the files added since, without the stored bytes
    /// changing.
    fn refresh(&mut self, diff: &Diff) -> Refreshed {
        if diff.is_empty() {
            Refreshed::UpToDate
        } else {
            Refreshed::NeedsRebuild
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::derived::{PolicyFingerprint, Predicate};
    use crate::snapshot::{FileId, SnapshotId, TableId};
    use std::collections::BTreeSet;

    fn plan(filter: &str) -> Plan {
        Plan::new(BTreeSet::from([4]), [filter.to_owned()])
    }

    /// A query whose plan and whose name can be set independently.
    ///
    /// They are separable on purpose: that is what lets a test pin the
    /// difference between matching on the name and matching on the plan.
    fn query(plan: Option<Plan>, plan_hash: u64) -> Query {
        Query {
            table: TableId("events".into()),
            snapshot: SnapshotId(812),
            policy: PolicyFingerprint(1),
            plan_hash,
            plan,
            projected: BTreeSet::from([4]),
            predicates: vec![Predicate::Eq { field: 4, value: 9 }],
            aggregate: None,
            nearest: None,
            join: None,
            approximate: false,
            stale: false,
        }
    }

    #[test]
    fn an_identical_plan_substitutes() {
        let c = ResultCache::rows_of(plan("tenant = 1"), 10, 100);
        assert_eq!(
            c.matches(&query(Some(plan("tenant = 1")), 0xBEEF)),
            Some(Rewrite::Substitute {
                unionable: true,
                rollup: None,
            })
        );
    }

    #[test]
    fn a_different_plan_does_not_match() {
        let c = ResultCache::rows_of(plan("tenant = 1"), 10, 100);
        assert_eq!(c.matches(&query(Some(plan("tenant = 2")), 0xBEEF)), None);
    }

    #[test]
    fn a_colliding_name_does_not_make_two_plans_one() {
        // The bug this guards: matching once compared `plan_hash`, so two
        // different plans sharing a 64-bit hash would have had one served the
        // other's stored rows. Here the names are *identical* and the plans
        // are not.
        let c = ResultCache::rows_of(plan("tenant = 1"), 10, 100);
        let colliding = query(Some(plan("tenant = 2")), 0xBEEF);
        assert_eq!(
            c.matches(&colliding),
            None,
            "a hash match is not a plan match"
        );
    }

    #[test]
    fn a_query_with_no_exact_plan_never_matches() {
        // The engine could not render this query faithfully, so there is no
        // way to establish that it computes what is stored. Refusing costs a
        // scan; guessing costs the wrong rows.
        let c = ResultCache::rows_of(plan("tenant = 1"), 10, 100);
        assert_eq!(c.matches(&query(None, 0xBEEF)), None);
    }

    #[test]
    fn filter_order_does_not_change_a_plan() {
        // A conjunction has no meaningful order, so these are one plan and
        // one cache entry rather than two.
        let one = Plan::new(
            BTreeSet::from([4]),
            ["a = 1".to_owned(), "b = 2".to_owned()],
        );
        let other = Plan::new(
            BTreeSet::from([4]),
            ["b = 2".to_owned(), "a = 1".to_owned()],
        );
        assert_eq!(one, other);

        let c = ResultCache::rows_of(one, 10, 100);
        assert!(c.matches(&query(Some(other), 1)).is_some());
    }

    #[test]
    fn a_different_projection_is_a_different_plan() {
        let c = ResultCache::rows_of(plan("tenant = 1"), 10, 100);
        let wider = Plan::new(BTreeSet::from([4, 7]), ["tenant = 1".to_owned()]);
        assert_eq!(c.matches(&query(Some(wider), 1)), None);
    }

    #[test]
    fn cost_scales_with_stored_bytes() {
        let prices = PriceTable::default();
        let small = ResultCache::rows_of(plan("a = 1"), 1, 100).cost(&prices);
        let large = ResultCache::rows_of(plan("a = 1"), 1, 100_000).cost(&prices);
        assert!(large.usd > small.usd);
        assert_eq!(small.bytes, 100);
    }

    #[test]
    fn an_unchanged_table_leaves_it_up_to_date() {
        let mut c = ResultCache::rows_of(plan("a = 1"), 1, 1);
        assert_eq!(c.refresh(&Diff::default()), Refreshed::UpToDate);
    }

    #[test]
    fn any_change_requires_a_rebuild() {
        let mut c = ResultCache::rows_of(plan("a = 1"), 1, 1);

        let appended = Diff {
            added: BTreeSet::from([FileId("new".into())]),
            ..Diff::default()
        };
        assert_eq!(c.refresh(&appended), Refreshed::NeedsRebuild);

        let deleted = Diff {
            redeleted: BTreeSet::from([FileId("old".into())]),
            ..Diff::default()
        };
        assert_eq!(c.refresh(&deleted), Refreshed::NeedsRebuild);
    }

    #[test]
    fn accessors_report_what_was_stored() {
        let c = ResultCache::rows_of(plan("a = 1"), 42, 4096);
        assert_eq!(c.plan(), &plan("a = 1"));
        assert_eq!(c.rows(), 42);
        assert_eq!(c.bytes(), 4096);
        assert_eq!(c.name(), "result");
    }
}

//! Quarry is a self-optimizing query engine over Iceberg tables on object
//! storage.
//!
//! The model has three concepts and one rule:
//!
//! - **Table** — an Iceberg table. Authoritative. Never modified by the
//!   optimizer.
//! - **Derived state** — bytes computed from a table at a known snapshot that
//!   can answer some queries more cheaply than the table can. Always
//!   disposable: losing all of it costs performance, never correctness.
//! - **Cost** — one currency for every decision.
//!
//! The rule decides when derived state may replace a scan. It is checked in
//! one place, for every kind of derived state, so that a wrong answer is
//! prevented by construction rather than by care.
//!
//! See `../core-design.md` for the design this implements, and `DEVPLAN.md`
//! for the phase this code is currently in.

#![forbid(unsafe_code)]

pub mod budget;
pub mod cost;
pub mod derived;
#[cfg(feature = "engine")]
pub mod engine;
pub mod explain;
pub mod facts;
#[cfg(feature = "iceberg")]
pub mod from_iceberg;
pub mod kinds;
pub mod layout;
pub mod place;
pub mod registry;
pub mod snapshot;
pub mod stable_hash;
pub mod workload;

//! Walks a table through four commits and explains the same query at each,
//! showing how the rule admits and refuses derived state as the table moves.
//!
//! ```sh
//! cargo run --example explain
//! ```

use std::collections::BTreeSet;

use quarry::budget::{Budget, Meter, Permit};
use quarry::cost::{PriceTable, Tier};
use quarry::derived::{Derived, DerivedId, Plan, PolicyFingerprint, Predicate, Query, Source};
use quarry::explain::Explain;
use quarry::kinds::{Index, ResultCache};
use quarry::place::{Distance, Place};
use quarry::registry::Registry;
use quarry::snapshot::{DeleteState, FileId, Snapshot, SnapshotGraph, SnapshotId, TableId};

const TENANT: u32 = 4;
const TENANT_42: u64 = 0x2A; // hash of the literal 42
const POLICY: PolicyFingerprint = PolicyFingerprint(7);

fn file(name: &str) -> FileId {
    FileId(name.to_owned())
}

/// The one plan the cached answer in this example was built for.
fn cached_plan() -> Plan {
    Plan::new(BTreeSet::from([TENANT]), ["tenant_id = 42".to_owned()])
}

fn main() {
    let table = TableId("events".into());
    let prices = PriceTable::default();

    // 810  two files
    // 811  appends c
    // 812  deletes rows from a          <- subtractive
    // 813  compacts a,b,c into merged   <- subtractive
    let graph = SnapshotGraph::new()
        .with(
            Snapshot::root(SnapshotId(810))
                .with_clean_file(file("a"))
                .with_clean_file(file("b")),
        )
        .with(
            Snapshot::child_of(SnapshotId(811), SnapshotId(810))
                .with_clean_file(file("a"))
                .with_clean_file(file("b"))
                .with_clean_file(file("c")),
        )
        .with(
            Snapshot::child_of(SnapshotId(812), SnapshotId(811))
                .with_file(file("a"), DeleteState(1))
                .with_clean_file(file("b"))
                .with_clean_file(file("c")),
        )
        .with(Snapshot::child_of(SnapshotId(813), SnapshotId(812)).with_clean_file(file("merged")));

    // Both built from snapshot 810, and never rebuilt.
    let mut registry = Registry::new();
    registry.register(Derived::new(
        DerivedId("tenant_idx".into()),
        Source {
            table: table.clone(),
            snapshot: SnapshotId(810),
        },
        POLICY,
        4096,
        Box::new(
            Index::new(TENANT)
                .with(TENANT_42, file("a"))
                .with_bytes(4096),
        ),
    ));
    registry.register(Derived::new(
        DerivedId("cached_answer".into()),
        Source {
            table: table.clone(),
            snapshot: SnapshotId(810),
        },
        POLICY,
        64,
        Box::new(ResultCache::rows_of(cached_plan(), 3, 64)),
    ));

    // SELECT ... FROM events WHERE tenant_id = 42
    //
    // The plan, not its hash, is what a stored result is matched against: two
    // different plans can share a hash, and serving on that would hand one
    // query another's answer.
    let query_at = |snapshot: i64| Query {
        table: table.clone(),
        snapshot: SnapshotId(snapshot),
        policy: POLICY,
        plan_hash: 0xC0FFEE,
        plan: Some(cached_plan()),
        projected: BTreeSet::from([TENANT]),
        predicates: vec![Predicate::Eq {
            field: TENANT,
            value: TENANT_42,
        }],
        aggregate: None,
        nearest: None,
        join: None,
        approximate: false,
        stale: false,
    };

    println!("Derived state built at snapshot 810, never rebuilt.\n");
    for snapshot in [810, 811, 812, 813] {
        let what_happened = match snapshot {
            810 => "as built",
            811 => "appended a file",
            812 => "deleted rows from a file",
            _ => "compacted",
        };
        println!("--- snapshot {snapshot} ({what_happened})");
        println!(
            "{}",
            Explain::plan(&query_at(snapshot), &registry, &graph, &prices)
        );
    }

    // Placement: the same bytes cost very different amounts depending on
    // where the worker is relative to them.
    let worker = Place::parse("/onprem/dc1/rack2/node7");
    println!("--- placement, from {worker}");
    for (label, replica) in [
        ("same node", "/onprem/dc1/rack2/node7"),
        ("same rack", "/onprem/dc1/rack2/node8"),
        ("other rack", "/onprem/dc1/rack9/node1"),
        ("other cloud", "/aws/us-west-2/usw2-az1/i-1"),
    ] {
        let distance = worker.distance(&Place::parse(replica));
        let cost = prices.price(1_000_000_000, Tier::Hot, distance, 0.0);
        println!("{label:<12} {distance:<6?} 1 GB = ${:.6}", cost.usd);
    }

    // Enforcement: a ceiling stops a scan part-way rather than after.
    println!("\n--- a 4 MB budget against ten 1 MB reads");
    let mut meter = Meter::new(Budget::bytes(4_000_000), prices);
    for read in 0..10 {
        if let Permit::Stop(exceeded) = meter.charge(1_000_000, Tier::Hot, Distance::Local) {
            println!("stopped on read {}: {exceeded:?}", read + 1);
            break;
        }
    }
    println!("spent: {} bytes", meter.spent().bytes);
}

//! A hash that means the same thing next year.
//!
//! [`std::hash::DefaultHasher`] is explicitly not stable across Rust releases,
//! which is fine for a value that lives in one process and fatal for one
//! written down. An index keyed on an unstable hash survives a compiler
//! upgrade as an index that matches **nothing** — a miss, not an error, so the
//! system quietly gets slower and the optimizer rebuilds everything with no
//! signal that anything broke.
//!
//! # What a collision costs, which is not the same everywhere
//!
//! ```text
//! pruning index   SAFE. Two values hashing alike means the index reports
//!                 files holding the other value too, so the scan reads
//!                 more than it needed. Over-selection; the predicate is
//!                 re-applied to rows regardless.
//!
//! plan identity   NOT SAFE. Two different queries hashing alike means one
//!                 is served the other's cached answer. See the warning on
//!                 [`StableHasher`]; this is a real, pre-existing gap and
//!                 not one a stable hash alone fixes.
//! ```
//!
//! # Versioning, because stability is not the same as permanence
//!
//! A stable algorithm still leaves one hazard: the *bytes fed to it*. Values
//! are hashed through their [`Hash`] implementations, which belong to `std`
//! and `arrow`, and either may change what it writes. So persisted derived
//! state carries [`HASH_VERSION`], and state stamped with a different version
//! is refused rather than probed. Invalidation becomes loud and rare instead
//! of silent.

use std::hash::{Hash, Hasher};

/// The version of everything that affects a persisted hash.
///
/// Bump this when the algorithm below changes, when the bytes fed to it
/// change, or when a dependency whose `Hash` implementation is used is
/// upgraded across a version that could reorder or reshape what it writes.
///
/// Refusing state with a different version costs a rebuild. Not refusing it
/// costs an index that silently matches nothing.
pub const HASH_VERSION: u32 = 1;

/// FNV-1a offset basis.
const FNV_OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
/// FNV-1a prime.
const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;

/// A fixed hash: FNV-1a over the bytes, then a SplitMix64 finalizer.
///
/// Both halves are published constants, so this produces the same value on
/// every platform and every compiler release, forever. FNV-1a alone has poor
/// avalanche — single-bit input changes barely move the high bits, which
/// clusters index buckets — and the finalizer fixes that for a handful of
/// arithmetic operations.
///
/// Not a cryptographic hash and not collision-resistant against an adversary
/// who picks inputs. That is acceptable for choosing which files to read,
/// where a collision costs extra I/O, and is **not** acceptable for deciding
/// that two query plans are the same.
#[derive(Clone, Debug)]
pub struct StableHasher {
    state: u64,
}

impl Default for StableHasher {
    fn default() -> Self {
        StableHasher { state: FNV_OFFSET }
    }
}

impl StableHasher {
    /// A fresh hasher.
    pub fn new() -> Self {
        Self::default()
    }

    /// Hash one value and finish, which is the common case.
    pub fn of<T: Hash + ?Sized>(value: &T) -> u64 {
        let mut hasher = StableHasher::new();
        value.hash(&mut hasher);
        hasher.finish()
    }
}

impl Hasher for StableHasher {
    fn write(&mut self, bytes: &[u8]) {
        for byte in bytes {
            self.state ^= *byte as u64;
            self.state = self.state.wrapping_mul(FNV_PRIME);
        }
    }

    // Every integer method is overridden, and that is not pedantry. The
    // default implementations write `to_ne_bytes()` — *native* endian — so a
    // hash written on x86 would not match one computed on a big-endian
    // machine. And `write_usize` defaults to the platform's pointer width, so
    // the same value would hash differently on 32- and 64-bit builds. Both
    // would have produced indexes that work until someone changes hardware.

    fn write_u8(&mut self, n: u8) {
        self.write(&[n]);
    }

    fn write_u16(&mut self, n: u16) {
        self.write(&n.to_le_bytes());
    }

    fn write_u32(&mut self, n: u32) {
        self.write(&n.to_le_bytes());
    }

    fn write_u64(&mut self, n: u64) {
        self.write(&n.to_le_bytes());
    }

    fn write_u128(&mut self, n: u128) {
        self.write(&n.to_le_bytes());
    }

    /// Widened to 64 bits, so a 32-bit build agrees with a 64-bit one.
    fn write_usize(&mut self, n: usize) {
        self.write(&(n as u64).to_le_bytes());
    }

    fn write_i8(&mut self, n: i8) {
        self.write_u8(n as u8);
    }

    fn write_i16(&mut self, n: i16) {
        self.write_u16(n as u16);
    }

    fn write_i32(&mut self, n: i32) {
        self.write_u32(n as u32);
    }

    fn write_i64(&mut self, n: i64) {
        self.write_u64(n as u64);
    }

    fn write_i128(&mut self, n: i128) {
        self.write_u128(n as u128);
    }

    fn write_isize(&mut self, n: isize) {
        self.write_usize(n as usize);
    }

    // `write_str` is deliberately *not* overridden: overriding it needs the
    // unstable `hasher_prefixfree_extras` feature. Its default writes the
    // string's bytes followed by `write_u8(0xff)`, which routes through the
    // override above, so strings are delimited — `("ab", "c")` and
    // `("a", "bc")` do not collide.
    //
    // That default is std's to change, which is the clearest example of why
    // `HASH_VERSION` exists: the algorithm here is fixed forever, but the
    // bytes handed to it are not entirely ours to fix.

    fn finish(&self) -> u64 {
        // SplitMix64's finalizer. Spreads FNV's weak high bits across the
        // whole word, so neighbouring inputs land in unrelated buckets.
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
        z ^ (z >> 31)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Pinned so a change to the algorithm cannot pass unnoticed.
    ///
    /// These were computed by an independent implementation of FNV-1a plus
    /// the SplitMix64 finalizer, not copied from this code's output — a test
    /// that records whatever the implementation currently does would pass for
    /// a broken implementation too.
    ///
    /// If they move, every persisted index is invalid and [`HASH_VERSION`]
    /// must be bumped in the same change. That is the whole point of writing
    /// them down.
    #[test]
    fn the_algorithm_is_pinned_to_known_values() {
        assert_eq!(StableHasher::of(""), 5_705_415_379_283_624_141);
        assert_eq!(StableHasher::of("a"), 1_819_190_507_042_467_253);
        assert_eq!(StableHasher::of("hello"), 10_509_149_385_209_626_834);
        assert_eq!(StableHasher::of(&0u64), 9_313_164_154_874_788_883);
        assert_eq!(StableHasher::of(&1i64), 6_676_229_981_160_887_125);
    }

    #[test]
    fn a_delimiter_keeps_concatenations_apart() {
        assert_ne!(
            StableHasher::of(&("ab", "c")),
            StableHasher::of(&("a", "bc")),
            "without a terminator these are the same byte stream"
        );
    }

    #[test]
    fn integers_hash_the_same_width_regardless_of_platform() {
        // `usize` is widened to 64 bits, so these agree on any target.
        assert_eq!(StableHasher::of(&7usize), StableHasher::of(&7u64));
        assert_eq!(StableHasher::of(&(-7isize)), StableHasher::of(&(-7i64)));
    }

    #[test]
    fn the_same_input_always_hashes_the_same() {
        for value in ["", "a", "some longer string", "\u{1f600}"] {
            assert_eq!(StableHasher::of(value), StableHasher::of(value));
        }
    }

    #[test]
    fn different_inputs_hash_differently() {
        let one = StableHasher::of(&1i64);
        let two = StableHasher::of(&2i64);
        assert_ne!(one, two);
    }

    #[test]
    fn neighbouring_inputs_do_not_cluster() {
        // FNV-1a alone barely moves the high bits between 1 and 2. The
        // finalizer is what makes this hold, and index selectivity depends
        // on it: clustered buckets mean an index that prunes nothing.
        let high_bits: Vec<u64> = (0i64..64).map(|n| StableHasher::of(&n) >> 56).collect();
        let distinct: std::collections::BTreeSet<u64> = high_bits.iter().copied().collect();
        assert!(
            distinct.len() > 32,
            "only {} distinct high bytes across 64 neighbours",
            distinct.len()
        );
    }

    #[test]
    fn hashing_in_pieces_matches_hashing_at_once() {
        let mut split = StableHasher::new();
        split.write(b"hel");
        split.write(b"lo");

        let mut whole = StableHasher::new();
        whole.write(b"hello");

        assert_eq!(split.finish(), whole.finish());
    }

    #[test]
    fn no_collisions_across_a_realistic_key_space() {
        // Index keys are usually identifiers. A collision here would cost
        // over-selection rather than a wrong answer, but it should still be
        // rare enough not to appear in a million values.
        let hashes: std::collections::HashSet<u64> =
            (0i64..1_000_000).map(|n| StableHasher::of(&n)).collect();
        assert_eq!(hashes.len(), 1_000_000);
    }
}

//! Where things are, and how far apart.
//!
//! Every placement question in the engine — which worker runs a scan task,
//! which replica it reads, whether a shuffle crosses an expensive boundary —
//! is the same question at a different scale: *how far, and what does that
//! distance cost?*
//!
//! A [`Place`] is a path down a locality hierarchy. [`Distance`] is derived
//! from how much of that path two places share, so the engine never needs to
//! know what any particular level *means*. A deployment with two levels and
//! one with five both work, which is what keeps this vendor-neutral.

use std::fmt;

/// Where something is, as a path down a locality hierarchy.
///
/// The levels are deliberately unnamed. `/onprem/dc1/rack2/node7` and
/// `/aws/us-west-2/usw2-az1/i-0abc123` are both valid and comparable; the
/// engine only ever asks how much of the path two places share.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Place {
    /// Position is not known.
    ///
    /// [`Distance::Far`] from everything, *including itself*: two workers that
    /// cannot say where they are might be anywhere, and assuming otherwise
    /// would let the scheduler make confident bad decisions. This is why
    /// unknown is a variant rather than a `/unknown/<host>` path — a path
    /// would compare equal to itself and report [`Distance::Local`].
    Unknown,
    /// A known position, outermost level first.
    At(Vec<String>),
}

impl Place {
    /// A place whose position is not known.
    pub fn unknown() -> Self {
        Place::Unknown
    }

    /// Parse a slash-separated path such as `/onprem/dc1/rack2/node7`.
    ///
    /// Leading, trailing, and repeated separators are ignored. A path with no
    /// segments is [`Place::Unknown`], since it locates nothing.
    pub fn parse(path: &str) -> Self {
        let segments: Vec<String> = path
            .split('/')
            .filter(|s| !s.is_empty())
            .map(str::to_owned)
            .collect();
        if segments.is_empty() {
            Place::Unknown
        } else {
            Place::At(segments)
        }
    }

    /// The path segments, or `None` if the position is not known.
    pub fn segments(&self) -> Option<&[String]> {
        match self {
            Place::Unknown => None,
            Place::At(s) => Some(s),
        }
    }

    /// How far this place is from `other`.
    ///
    /// Let `shared` be the number of leading segments the two paths have in
    /// common and `depth` the deeper of the two:
    ///
    /// - `shared == depth` — the same position: [`Distance::Local`]
    /// - `shared == depth - 1` — siblings, or a parent and its child:
    ///   [`Distance::Near`]
    /// - otherwise: [`Distance::Far`]
    ///
    /// Either place being [`Place::Unknown`] yields [`Distance::Far`].
    pub fn distance(&self, other: &Place) -> Distance {
        let (a, b) = match (self.segments(), other.segments()) {
            (Some(a), Some(b)) => (a, b),
            _ => return Distance::Far,
        };
        let shared = a.iter().zip(b).take_while(|(x, y)| x == y).count();
        let depth = a.len().max(b.len());
        if shared == depth {
            Distance::Local
        } else if shared + 1 == depth {
            Distance::Near
        } else {
            Distance::Far
        }
    }
}

impl fmt::Display for Place {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Place::Unknown => f.write_str("<unknown>"),
            Place::At(segments) => {
                for segment in segments {
                    write!(f, "/{segment}")?;
                }
                Ok(())
            }
        }
    }
}

/// How far apart two [`Place`]s are.
///
/// Three levels is enough to price placement today. The path representation in
/// [`Place`] means that distinguishing rack from data center, or adding a
/// cross-cloud boundary, later changes a price table rather than this type.
///
/// Ordered nearest first, so `min` picks the better option.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Distance {
    /// The same position. Reads are effectively free.
    Local,
    /// One level apart: siblings, or a parent and its child.
    Near,
    /// Anywhere else, or an unknown position. Assume the worst.
    Far,
}

#[cfg(test)]
mod tests {
    use super::*;

    fn p(path: &str) -> Place {
        Place::parse(path)
    }

    #[test]
    fn identical_places_are_local() {
        assert_eq!(
            p("/onprem/dc1/rack2/node7").distance(&p("/onprem/dc1/rack2/node7")),
            Distance::Local
        );
    }

    #[test]
    fn siblings_are_near() {
        assert_eq!(
            p("/onprem/dc1/rack2/node7").distance(&p("/onprem/dc1/rack2/node8")),
            Distance::Near
        );
    }

    #[test]
    fn a_parent_and_its_child_are_near() {
        assert_eq!(
            p("/onprem/dc1/rack2").distance(&p("/onprem/dc1/rack2/node7")),
            Distance::Near
        );
    }

    #[test]
    fn different_racks_are_far() {
        assert_eq!(
            p("/onprem/dc1/rack2/node7").distance(&p("/onprem/dc1/rack9/node7")),
            Distance::Far
        );
    }

    #[test]
    fn different_clouds_are_far() {
        assert_eq!(
            p("/aws/us-west-2/usw2-az1/i-1").distance(&p("/gcp/us-central1/a/n-1")),
            Distance::Far
        );
    }

    #[test]
    fn unknown_is_far_from_everything_including_itself() {
        let here = p("/onprem/dc1/rack2/node7");
        assert_eq!(Place::unknown().distance(&here), Distance::Far);
        assert_eq!(here.distance(&Place::unknown()), Distance::Far);
        assert_eq!(
            Place::unknown().distance(&Place::unknown()),
            Distance::Far,
            "two workers that cannot locate themselves might be anywhere"
        );
    }

    #[test]
    fn distance_is_symmetric() {
        let places = [
            p("/a"),
            p("/a/b"),
            p("/a/b/c"),
            p("/a/b/d"),
            p("/z/y/x"),
            Place::unknown(),
        ];
        for x in &places {
            for y in &places {
                assert_eq!(
                    x.distance(y),
                    y.distance(x),
                    "distance {x} <-> {y} is not symmetric"
                );
            }
        }
    }

    #[test]
    fn nearest_sorts_first() {
        let mut ds = [Distance::Far, Distance::Local, Distance::Near];
        ds.sort();
        assert_eq!(ds, [Distance::Local, Distance::Near, Distance::Far]);
    }

    #[test]
    fn parsing_ignores_separator_noise() {
        assert_eq!(p("/a/b/"), p("a//b"));
        assert_eq!(p("/a/b/"), Place::At(vec!["a".into(), "b".into()]));
    }

    #[test]
    fn a_path_that_locates_nothing_is_unknown() {
        assert_eq!(p(""), Place::Unknown);
        assert_eq!(p("/"), Place::Unknown);
    }

    #[test]
    fn display_round_trips() {
        assert_eq!(p("/onprem/dc1/rack2").to_string(), "/onprem/dc1/rack2");
        assert_eq!(Place::unknown().to_string(), "<unknown>");
    }
}

//! Deriving a [`SnapshotGraph`] from real Iceberg table metadata.
//!
//! The rule needs two things from a table: which snapshot descends from which,
//! and which data files are live at each — with enough fidelity that a change
//! in what is *deleted* shows up even when no data file was added or removed.
//! Iceberg has all of it; this walks the metadata and manifests to extract it.
//!
//! Behind the `iceberg` feature, and independent of `engine`: the bridge is
//! pure metadata, so it needs no query engine, and the engine needs no Iceberg.
//!
//! # How deletes are handled, and why coarsely
//!
//! [`DeleteState`] only has to *change* when the deletes affecting a data file
//! change; it is an opaque fingerprint, not a description. Attributing deletes
//! to individual data files is possible in part — a position delete file may
//! name a `referenced_data_file` — but equality deletes apply by value across a
//! whole partition, so exact attribution is not generally available.
//!
//! So this errs coarse and safe:
//!
//! ```text
//! no delete files in the snapshot
//!     → every data file is DeleteState::NONE
//!
//! any delete files in the snapshot
//!     → every data file gets the SAME fingerprint, derived from the
//!       whole delete-file set
//! ```
//!
//! The consequence is over-invalidation, never under: a delete anywhere in the
//! table makes every substituting piece of derived state look stale, while
//! pruning keeps working because pruning tolerates any change. Wrong in the
//! direction of slow rather than the direction of wrong.

use std::collections::{BTreeMap, BTreeSet};
use std::hash::{Hash, Hasher};

use iceberg::io::FileIO;
use iceberg::spec::{DataContentType, ManifestStatus, TableMetadata};

use crate::derived::FieldId;
use crate::snapshot::{DeleteState, FileId, Snapshot, SnapshotGraph, SnapshotId, TableId};

/// The table's identity, independent of its name.
///
/// Iceberg's table UUID, so that renaming a table does not orphan the derived
/// state built from it.
pub fn table_id(metadata: &TableMetadata) -> TableId {
    TableId(metadata.uuid().to_string())
}

/// The path a storage layer would use for a file Iceberg records.
///
/// Iceberg records data file locations as URIs, which the object store
/// addresses as a path *within* a store identified separately. So
/// `s3://bucket/data/a.parquet` becomes `data/a.parquet`, and the bucket is
/// carried by the store's own URL.
///
/// This is the one place catalog identity and storage identity are reconciled,
/// and doing it here means [`FileId`] means the same thing everywhere: the rule
/// reasons about it, and the scan reads it, without either converting.
pub fn object_path(file_path: &str) -> String {
    match file_path.find("://") {
        None => file_path.to_owned(),
        Some(scheme_end) => {
            let after_scheme = &file_path[scheme_end + 3..];
            match after_scheme.find('/') {
                // scheme://authority/path → path
                Some(authority_end) => after_scheme[authority_end + 1..].to_owned(),
                // scheme://authority with no path at all
                None => String::new(),
            }
        }
    }
}

/// The snapshot a query would read by default.
pub fn current_snapshot(metadata: &TableMetadata) -> Option<SnapshotId> {
    metadata
        .current_snapshot()
        .map(|snapshot| SnapshotId(snapshot.snapshot_id()))
}

/// Build a [`SnapshotGraph`] covering every snapshot the metadata retains.
///
/// Reads each snapshot's manifest list and manifests, so it costs one round
/// trip per manifest. Snapshots that have been expired are simply absent, and
/// the rule already refuses derived state whose source snapshot it cannot find.
pub async fn snapshot_graph(
    metadata: &TableMetadata,
    file_io: &FileIO,
) -> iceberg::Result<SnapshotGraph> {
    let mut graph = SnapshotGraph::new();

    for snapshot in metadata.snapshots() {
        let contents = read_snapshot(snapshot, metadata, file_io).await?;

        let mut built = match snapshot.parent_snapshot_id() {
            Some(parent) => {
                Snapshot::child_of(SnapshotId(snapshot.snapshot_id()), SnapshotId(parent))
            }
            None => Snapshot::root(SnapshotId(snapshot.snapshot_id())),
        };
        let deletes = fingerprint(&contents.delete_files);
        for file in contents.data_files {
            built = built.with_file(file, deletes);
        }
        graph.insert(built);
    }

    Ok(graph)
}

/// Every data file live at `snapshot`, with the deletes applying to it.
///
/// Exposed because it is useful on its own: a caller wanting to register the
/// table's Parquet objects needs exactly this list.
pub async fn live_data_files(
    metadata: &TableMetadata,
    file_io: &FileIO,
    at: SnapshotId,
) -> iceberg::Result<BTreeMap<FileId, u64>> {
    let Some(snapshot) = metadata.snapshot_by_id(at.0) else {
        return Ok(BTreeMap::new());
    };
    let contents = read_snapshot(snapshot, metadata, file_io).await?;
    Ok(contents.sizes)
}

/// Per-file value ranges for one field, as the manifests record them.
///
/// The input the index gate needs, and it costs nothing to obtain: Iceberg
/// already stores a lower and upper bound per field per data file, so whether
/// an index could beat the format's own pruning is answerable from metadata
/// alone. See [`Spread`](crate::layout::Spread).
///
/// Files that record no bound for the field are omitted, which the estimate
/// treats as files that must always be read — so a table with no statistics
/// degrades to "assume the worst" rather than to a wrong answer.
///
/// Only orderable numeric and temporal types are mapped. Strings and binary
/// are left out: they have bounds, but projecting them onto a number to
/// compare range *widths* would invent a distance that does not exist.
pub async fn bounds_by_field(
    metadata: &TableMetadata,
    file_io: &FileIO,
    at: SnapshotId,
) -> iceberg::Result<BTreeMap<FieldId, Vec<(f64, f64)>>> {
    let Some(snapshot) = metadata.snapshot_by_id(at.0) else {
        return Ok(BTreeMap::new());
    };

    // Every field in one pass. Walking the manifests per field would multiply
    // the metadata reads by the width of the table for no reason.
    let mut bounds: BTreeMap<FieldId, Vec<(f64, f64)>> = BTreeMap::new();
    let manifest_list = snapshot.load_manifest_list(file_io, metadata).await?;
    for manifest_file in manifest_list.entries() {
        let manifest = manifest_file.load_manifest(file_io).await?;
        for entry in manifest.entries() {
            if entry.status() == ManifestStatus::Deleted {
                continue;
            }
            let data_file = entry.data_file();
            if data_file.content_type() != DataContentType::Data {
                continue;
            }
            for (key, low) in data_file.lower_bounds() {
                let Some(low) = as_number(low) else { continue };
                let Some(high) = data_file.upper_bounds().get(key).and_then(as_number) else {
                    continue;
                };
                bounds.entry(*key as FieldId).or_default().push((low, high));
            }
        }
    }
    Ok(bounds)
}

/// One bound as a number, if the type has a meaningful distance.
fn as_number(bound: &iceberg::spec::Datum) -> Option<f64> {
    use iceberg::spec::PrimitiveLiteral;
    match bound.literal() {
        PrimitiveLiteral::Int(value) => Some(*value as f64),
        PrimitiveLiteral::Long(value) => Some(*value as f64),
        PrimitiveLiteral::Float(value) => Some(value.into_inner() as f64),
        PrimitiveLiteral::Double(value) => Some(value.into_inner()),
        // Booleans, strings, binary, decimals and UUIDs are ordered but have
        // no distance that range widths could be compared across.
        _ => None,
    }
}

struct Contents {
    data_files: BTreeSet<FileId>,
    delete_files: BTreeSet<String>,
    sizes: BTreeMap<FileId, u64>,
}

async fn read_snapshot(
    snapshot: &iceberg::spec::Snapshot,
    metadata: &TableMetadata,
    file_io: &FileIO,
) -> iceberg::Result<Contents> {
    let mut contents = Contents {
        data_files: BTreeSet::new(),
        delete_files: BTreeSet::new(),
        sizes: BTreeMap::new(),
    };

    let manifest_list = snapshot.load_manifest_list(file_io, metadata).await?;
    for manifest_file in manifest_list.entries() {
        let manifest = manifest_file.load_manifest(file_io).await?;
        for entry in manifest.entries() {
            // A `Deleted` entry records that a file left the table in this
            // snapshot; it is not live. `Existing` and `Added` both are.
            if entry.status() == ManifestStatus::Deleted {
                continue;
            }
            let data_file = entry.data_file();
            match data_file.content_type() {
                DataContentType::Data => {
                    let id = FileId(object_path(data_file.file_path()));
                    contents
                        .sizes
                        .insert(id.clone(), data_file.file_size_in_bytes());
                    contents.data_files.insert(id);
                }
                DataContentType::PositionDeletes | DataContentType::EqualityDeletes => {
                    contents
                        .delete_files
                        .insert(object_path(data_file.file_path()));
                }
            }
        }
    }

    Ok(contents)
}

/// A fingerprint of a snapshot's delete files.
///
/// Any change to the set changes the value, which is all [`DeleteState`]
/// promises. An empty set is [`DeleteState::NONE`] so that an append-only table
/// never looks as though anything was deleted.
fn fingerprint(delete_files: &BTreeSet<String>) -> DeleteState {
    if delete_files.is_empty() {
        return DeleteState::NONE;
    }
    let mut hasher = crate::stable_hash::StableHasher::new();
    for path in delete_files {
        path.hash(&mut hasher);
    }
    // Never collide with NONE: a table that has deletes must not look clean.
    DeleteState(hasher.finish() | 1)
}

