//! What a storage backend can tell us beyond returning bytes.
//!
//! This is the capability boundary the design cares most about. A backend that
//! knows where its objects live, and which of them are cold, lets the
//! optimizer make decisions a byte-counting one cannot. A backend that knows
//! none of that must still work, and must not be a special case.
//!
//! So every question is optional, and the answers are resolved into concrete
//! values in exactly one place ([`resolve`]). No caller branches on which
//! backend it has, and nothing in the engine names one.
//!
//! Deliberately dependency-free, and in the core rather than under `engine`:
//! it is a boundary, not an implementation detail. Objects are named by the
//! path string the storage layer uses, which is not necessarily the same string
//! a catalog records for a data file.

use std::collections::BTreeMap;
use std::fmt;

use crate::cost::Tier;
use crate::place::{Distance, Place};
use crate::snapshot::Commits;

/// What a backend can say about its objects.
///
/// All methods return `None` for "cannot say". See [`resolve`] for what is
/// assumed then, and why the two dimensions do *not* default the same way.
pub trait StorageFacts: fmt::Debug + Send + Sync {
    /// Which tier `object` is stored in.
    fn tier(&self, object: &str) -> Option<Tier>;

    /// How far `object` is from a reader at `reader`.
    fn distance(&self, object: &str, reader: &Place) -> Option<Distance>;

    /// The commit log this backend pushes into, if it can.
    ///
    /// A backend that sees commits — a catalog, a volume server — hands the
    /// optimizer the same [`Commits`] it notes them on, and a round hears the
    /// table moved without asking. `None` means poll: the table's own
    /// snapshot is the fallback and nothing is lost.
    fn commits(&self) -> Option<Commits> {
        None
    }
}

/// What the engine concluded about an object, after defaults.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Resolved {
    /// The tier to price against.
    pub tier: Tier,
    /// The distance to price against.
    pub distance: Distance,
    /// Whether the backend actually answered, or defaults were used.
    pub assumed: bool,
}

/// Turn what a backend will say into what the engine will use.
///
/// The two defaults are deliberately not symmetric, and getting this wrong
/// would be expensive in opposite directions:
///
/// ```text
/// unknown distance → Far
///     If a backend cannot say where an object is, we must not claim
///     locality. Far is also usually the truth: object storage is remote.
///
/// unknown tier → Hot
///     NOT the worst case, on purpose. A backend that cannot report tiers
///     almost certainly does not have them — plain S3 is uniformly hot.
///     Assuming Cold would multiply every price by the cold factor, which
///     overprices every plain-S3 read and would abort budgeted queries
///     that should have succeeded.
/// ```
///
/// The design said to "assume the worst" for both. That is right for distance
/// and wrong for tier: pessimism about a dimension the backend does not *have*
/// is not caution, it is a made-up cost.
pub fn resolve(facts: &dyn StorageFacts, object: &str, reader: &Place) -> Resolved {
    let tier = facts.tier(object);
    let distance = facts.distance(object, reader);
    Resolved {
        tier: tier.unwrap_or(Tier::Hot),
        distance: distance.unwrap_or(Distance::Far),
        assumed: tier.is_none() || distance.is_none(),
    }
}

/// A backend that reports nothing: plain S3, GCS, Azure Blob.
///
/// Everything resolves to hot and [`Distance::Far`], so placement degrades to
/// load balancing and the cost model still works. The same code path as a
/// backend that answers everything — no special case.
#[derive(Clone, Copy, Debug, Default)]
pub struct OpaqueStorage;

impl StorageFacts for OpaqueStorage {
    fn tier(&self, _object: &str) -> Option<Tier> {
        None
    }

    fn distance(&self, _object: &str, _reader: &Place) -> Option<Distance> {
        None
    }
}

/// Where a set of objects live, and how cold they are.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Placement {
    /// Which tier these objects are stored in.
    pub tier: Tier,
    /// Where these objects physically are.
    pub at: Place,
}

impl Placement {
    /// Hot objects at `at`.
    pub fn hot(at: Place) -> Self {
        Placement {
            tier: Tier::Hot,
            at,
        }
    }

    /// Cold objects at `at`.
    pub fn cold(at: Place) -> Self {
        Placement {
            tier: Tier::Cold,
            at,
        }
    }
}

/// A backend that reports placement per path prefix.
///
/// Stands in for a store that knows its own topology — SeaweedFS tracks a data
/// center, rack and node for every volume, and a tier for every one that has
/// been moved to cloud storage. Longest matching prefix wins, so a whole
/// bucket can be declared and individual paths overridden.
#[derive(Clone, Debug, Default)]
pub struct PlacedStorage {
    by_prefix: BTreeMap<String, Placement>,
    fallback: Option<Placement>,
}

impl PlacedStorage {
    /// A backend that can place nothing yet.
    pub fn new() -> Self {
        Self::default()
    }

    /// Declare where objects under `prefix` live.
    pub fn with_prefix(mut self, prefix: impl Into<String>, placement: Placement) -> Self {
        self.by_prefix.insert(prefix.into(), placement);
        self
    }

    /// Declare where everything else lives.
    ///
    /// Without this, an object matching no prefix is reported as unknown —
    /// which is honest, and resolves to hot and far.
    pub fn with_fallback(mut self, placement: Placement) -> Self {
        self.fallback = Some(placement);
        self
    }

    fn placement_of(&self, object: &str) -> Option<&Placement> {
        self.by_prefix
            .iter()
            .filter(|(prefix, _)| object.starts_with(prefix.as_str()))
            .max_by_key(|(prefix, _)| prefix.len())
            .map(|(_, placement)| placement)
            .or(self.fallback.as_ref())
    }
}

impl StorageFacts for PlacedStorage {
    fn tier(&self, object: &str) -> Option<Tier> {
        Some(self.placement_of(object)?.tier)
    }

    fn distance(&self, object: &str, reader: &Place) -> Option<Distance> {
        Some(reader.distance(&self.placement_of(object)?.at))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn here() -> Place {
        Place::parse("/onprem/dc1/rack2/node7")
    }

    #[test]
    fn a_backend_with_nothing_to_push_offers_no_log() {
        assert!(OpaqueStorage.commits().is_none());
        assert!(PlacedStorage::new().commits().is_none());
    }

    #[test]
    fn a_backend_that_hears_commits_shares_its_log() {
        use crate::snapshot::{Commits, SnapshotId, TableId};

        #[derive(Debug)]
        struct HearsCommits(Commits);
        impl StorageFacts for HearsCommits {
            fn tier(&self, _: &str) -> Option<Tier> {
                None
            }
            fn distance(&self, _: &str, _: &Place) -> Option<Distance> {
                None
            }
            fn commits(&self) -> Option<Commits> {
                Some(self.0.clone())
            }
        }

        let facts = HearsCommits(Commits::new());
        let shared = facts.commits().expect("a log to share");
        shared.note(TableId("events".into()), SnapshotId(7));

        // The same log the optimizer would hold hears what the backend noted.
        assert_eq!(facts.0.drain()[&TableId("events".into())], SnapshotId(7));
    }

    #[test]
    fn a_backend_that_knows_nothing_resolves_to_hot_and_far() {
        let resolved = resolve(&OpaqueStorage, "bucket/data/a.parquet", &here());
        assert_eq!(
            resolved,
            Resolved {
                tier: Tier::Hot,
                distance: Distance::Far,
                assumed: true,
            }
        );
    }

    #[test]
    fn unknown_tier_is_hot_rather_than_cold() {
        // A backend without tiers must not be priced as if everything were
        // cold; that would overprice every read by the cold multiplier.
        #[derive(Debug)]
        struct KnowsPlaceOnly;
        impl StorageFacts for KnowsPlaceOnly {
            fn tier(&self, _object: &str) -> Option<Tier> {
                None
            }
            fn distance(&self, _object: &str, _reader: &Place) -> Option<Distance> {
                Some(Distance::Local)
            }
        }

        let resolved = resolve(&KnowsPlaceOnly, "a", &here());
        assert_eq!(resolved.tier, Tier::Hot);
        assert_eq!(resolved.distance, Distance::Local);
        assert!(resolved.assumed, "the tier was assumed");
    }

    #[test]
    fn a_fully_answering_backend_is_not_marked_assumed() {
        let facts = PlacedStorage::new().with_fallback(Placement::hot(here()));
        let resolved = resolve(&facts, "a", &here());
        assert!(!resolved.assumed);
        assert_eq!(resolved.distance, Distance::Local);
    }

    #[test]
    fn placement_makes_a_local_object_local() {
        let facts = PlacedStorage::new()
            .with_prefix("hot/", Placement::hot(here()))
            .with_prefix(
                "far/",
                Placement::hot(Place::parse("/aws/us-west-2/az1/i-1")),
            );

        assert_eq!(
            resolve(&facts, "hot/a.parquet", &here()).distance,
            Distance::Local
        );
        assert_eq!(
            resolve(&facts, "far/a.parquet", &here()).distance,
            Distance::Far
        );
    }

    #[test]
    fn the_longest_matching_prefix_wins() {
        let facts = PlacedStorage::new()
            .with_prefix("bucket/", Placement::hot(Place::parse("/aws/us-west-2")))
            .with_prefix(
                "bucket/archive/",
                Placement::cold(Place::parse("/aws/us-west-2")),
            );

        assert_eq!(resolve(&facts, "bucket/a", &here()).tier, Tier::Hot);
        assert_eq!(
            resolve(&facts, "bucket/archive/a", &here()).tier,
            Tier::Cold,
            "the more specific declaration must win"
        );
    }

    #[test]
    fn an_unmatched_object_falls_back_or_is_unknown() {
        let strict = PlacedStorage::new().with_prefix("known/", Placement::hot(here()));
        assert!(strict.tier("other/a").is_none());
        assert!(resolve(&strict, "other/a", &here()).assumed);

        let lenient = strict.clone().with_fallback(Placement::cold(here()));
        assert_eq!(lenient.tier("other/a"), Some(Tier::Cold));
    }

    #[test]
    fn a_reader_elsewhere_sees_the_same_object_as_farther() {
        let facts = PlacedStorage::new().with_fallback(Placement::hot(here()));

        assert_eq!(resolve(&facts, "a", &here()).distance, Distance::Local);
        assert_eq!(
            resolve(&facts, "a", &Place::parse("/onprem/dc1/rack2/node8")).distance,
            Distance::Near
        );
        assert_eq!(
            resolve(&facts, "a", &Place::parse("/onprem/dc9/rack1/node1")).distance,
            Distance::Far
        );
        assert_eq!(
            resolve(&facts, "a", &Place::unknown()).distance,
            Distance::Far,
            "a reader that cannot locate itself is far from everything"
        );
    }

    #[test]
    fn a_cold_object_prices_above_a_hot_one() {
        use crate::cost::PriceTable;

        let facts = PlacedStorage::new()
            .with_prefix("hot/", Placement::hot(here()))
            .with_prefix("cold/", Placement::cold(here()));
        let prices = PriceTable::default();

        let hot = resolve(&facts, "hot/a", &here());
        let cold = resolve(&facts, "cold/a", &here());
        assert!(
            prices.byte_usd(cold.tier, cold.distance) > prices.byte_usd(hot.tier, hot.distance)
        );
    }
}

//! Table identity, snapshots, and what changed between them.
//!
//! Two questions the rule in [`crate::derived`] needs answered, and both are
//! easy to get subtly wrong:
//!
//! 1. **Lineage.** Is the snapshot being queried a descendant of the one some
//!    derived state was built from? A rollback produces a *sibling*, not a
//!    descendant, so derived state built on the abandoned branch must not be
//!    used even though its snapshot id is older.
//!
//! 2. **What changed.** A commit that only adds delete files changes which
//!    rows are live while adding and removing no data file at all. Diffing
//!    file sets alone misses it, and the result is wrong answers rather than a
//!    missed optimization.

use std::collections::{BTreeMap, BTreeSet};

/// Identifies a table, independent of its name.
///
/// Keyed on identity rather than name so that renaming a table does not
/// orphan the derived state built from it.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct TableId(pub String);

/// Identifies a snapshot within a table.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct SnapshotId(pub i64);

/// Identifies a data file within a table.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct FileId(pub String);

/// An opaque fingerprint of the deletes that apply to one data file.
///
/// Quarry does not model delete files themselves; it only needs to know
/// whether the set applying to a data file has *changed*. Any value that
/// changes when the deletes change will do — in a real catalog this is derived
/// from the delete-file list or deletion-vector state for the file.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct DeleteState(pub u64);

impl DeleteState {
    /// No rows in this file are deleted.
    pub const NONE: DeleteState = DeleteState(0);
}

/// One committed state of a table: which data files are live, and what is
/// deleted from each.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Snapshot {
    id: SnapshotId,
    parent: Option<SnapshotId>,
    files: BTreeMap<FileId, DeleteState>,
}

impl Snapshot {
    /// A snapshot with no parent: the first commit, or the root of a branch.
    pub fn root(id: SnapshotId) -> Self {
        Snapshot {
            id,
            parent: None,
            files: BTreeMap::new(),
        }
    }

    /// A snapshot descending from `parent`.
    pub fn child_of(id: SnapshotId, parent: SnapshotId) -> Self {
        Snapshot {
            id,
            parent: Some(parent),
            files: BTreeMap::new(),
        }
    }

    /// Add a live data file with the given deletes applied.
    pub fn with_file(mut self, file: FileId, deletes: DeleteState) -> Self {
        self.files.insert(file, deletes);
        self
    }

    /// Add a live data file with no deletes applied.
    pub fn with_clean_file(self, file: FileId) -> Self {
        self.with_file(file, DeleteState::NONE)
    }

    /// This snapshot's id.
    pub fn id(&self) -> SnapshotId {
        self.id
    }

    /// The snapshot this one descends from, if any.
    pub fn parent(&self) -> Option<SnapshotId> {
        self.parent
    }

    /// The live data files and their delete state.
    pub fn files(&self) -> &BTreeMap<FileId, DeleteState> {
        &self.files
    }
}

/// A shared log of commits: which table moved to which snapshot.
///
/// Push rather than poll. Whatever learns of a commit — a catalog, a
/// re-pointed table, a test — notes it, and the optimizer drains it each
/// round to learn the newest known position of each table. A missed or
/// duplicated note costs nothing: the table's own snapshot is always the
/// fallback.
#[derive(Clone, Debug, Default)]
pub struct Commits(std::sync::Arc<std::sync::Mutex<Vec<(TableId, SnapshotId)>>>);

impl Commits {
    /// An empty log.
    pub fn new() -> Self {
        Self::default()
    }

    /// Note that `table` moved to `snapshot`.
    pub fn note(&self, table: TableId, snapshot: SnapshotId) {
        self.0.lock().expect("commits").push((table, snapshot));
    }

    /// The newest snapshot noted per table, draining the log.
    ///
    /// Duplicates and out-of-order notes collapse to the maximum per table:
    /// the only fact a commit carries is that a newer snapshot exists.
    pub fn drain(&self) -> BTreeMap<TableId, SnapshotId> {
        self.0.lock().expect("commits").drain(..).fold(
            BTreeMap::new(),
            |mut latest, (table, snapshot)| {
                let entry = latest.entry(table).or_insert(snapshot);
                if snapshot > *entry {
                    *entry = snapshot;
                }
                latest
            },
        )
    }
}

/// What changed between two snapshots, classified by whether derived state
/// built from the earlier one can be repaired by reading more data.
///
/// The distinction is the whole point of this type:
///
/// - [`Diff::added`] is **additive**. Derived state that missed these files is
///   still correct as far as it goes, so scanning them alongside it produces
///   the right answer.
/// - [`Diff::removed`] and [`Diff::redeleted`] are **subtractive**. Derived
///   state may contain rows that are no longer live, and no amount of extra
///   reading removes them. Such derived state cannot be used, only rebuilt.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Diff {
    /// Files live in the later snapshot but not the earlier one.
    pub added: BTreeSet<FileId>,
    /// Files live in the earlier snapshot but not the later one.
    pub removed: BTreeSet<FileId>,
    /// Files live in both, whose deletes changed.
    pub redeleted: BTreeSet<FileId>,
}

impl Diff {
    /// Whether nothing changed at all.
    pub fn is_empty(&self) -> bool {
        self.added.is_empty() && self.removed.is_empty() && self.redeleted.is_empty()
    }

    /// Whether every change only *adds* rows.
    ///
    /// When true, derived state built from the earlier snapshot can serve a
    /// query at the later one by being unioned with a scan of
    /// [`Diff::added`]. When false, it cannot be used at all.
    pub fn is_purely_additive(&self) -> bool {
        self.removed.is_empty() && self.redeleted.is_empty()
    }
}

/// The snapshots of one table and how they descend from each other.
#[derive(Clone, Debug, Default)]
pub struct SnapshotGraph {
    snapshots: BTreeMap<SnapshotId, Snapshot>,
}

impl SnapshotGraph {
    /// An empty graph.
    pub fn new() -> Self {
        Self::default()
    }

    /// Record a snapshot, replacing any existing one with the same id.
    pub fn insert(&mut self, snapshot: Snapshot) {
        self.snapshots.insert(snapshot.id(), snapshot);
    }

    /// Builder form of [`SnapshotGraph::insert`].
    pub fn with(mut self, snapshot: Snapshot) -> Self {
        self.insert(snapshot);
        self
    }

    /// Look up a snapshot.
    pub fn get(&self, id: SnapshotId) -> Option<&Snapshot> {
        self.snapshots.get(&id)
    }

    /// Whether `candidate` is `ancestor` itself, or descends from it.
    ///
    /// Walks parent links upward from `candidate`, so a rolled-back branch is
    /// correctly *not* an ancestor of the branch that replaced it. Returns
    /// `false` if either snapshot is unknown, or if parent links form a cycle,
    /// rather than looping or panicking: an unverifiable lineage must not be
    /// reported as valid.
    pub fn is_descendant_or_self(&self, candidate: SnapshotId, ancestor: SnapshotId) -> bool {
        if !self.snapshots.contains_key(&candidate) || !self.snapshots.contains_key(&ancestor) {
            return false;
        }
        let mut at = Some(candidate);
        let mut steps = 0;
        while let Some(id) = at {
            if id == ancestor {
                return true;
            }
            steps += 1;
            if steps > self.snapshots.len() {
                return false; // cycle
            }
            at = self.snapshots.get(&id).and_then(Snapshot::parent);
        }
        false
    }

    /// Classify what changed between two snapshots.
    ///
    /// Compares live file sets *and* the delete state of files present in
    /// both, so a commit that only adds delete files is reported in
    /// [`Diff::redeleted`]. Returns `None` if either snapshot is unknown.
    pub fn diff(&self, from: SnapshotId, to: SnapshotId) -> Option<Diff> {
        let before = self.get(from)?.files();
        let after = self.get(to)?.files();

        let mut diff = Diff::default();
        for (file, deletes) in after {
            match before.get(file) {
                None => {
                    diff.added.insert(file.clone());
                }
                Some(was) if was != deletes => {
                    diff.redeleted.insert(file.clone());
                }
                Some(_) => {}
            }
        }
        for file in before.keys() {
            if !after.contains_key(file) {
                diff.removed.insert(file.clone());
            }
        }
        Some(diff)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn f(name: &str) -> FileId {
        FileId(name.to_owned())
    }

    fn s(id: i64) -> SnapshotId {
        SnapshotId(id)
    }

    fn t(name: &str) -> TableId {
        TableId(name.to_owned())
    }

    /// 810 -> 811 -> 812, with one file added at each step.
    fn linear() -> SnapshotGraph {
        SnapshotGraph::new()
            .with(Snapshot::root(s(810)).with_clean_file(f("a")))
            .with(
                Snapshot::child_of(s(811), s(810))
                    .with_clean_file(f("a"))
                    .with_clean_file(f("b")),
            )
            .with(
                Snapshot::child_of(s(812), s(811))
                    .with_clean_file(f("a"))
                    .with_clean_file(f("b"))
                    .with_clean_file(f("c")),
            )
    }

    #[test]
    fn a_snapshot_is_its_own_descendant() {
        let g = linear();
        assert!(g.is_descendant_or_self(s(812), s(812)));
    }

    #[test]
    fn descent_follows_parent_links() {
        let g = linear();
        assert!(g.is_descendant_or_self(s(812), s(810)));
        assert!(g.is_descendant_or_self(s(812), s(811)));
        assert!(!g.is_descendant_or_self(s(810), s(812)));
    }

    #[test]
    fn a_rolled_back_branch_is_not_an_ancestor() {
        // 811 is abandoned; 812 is committed against 810 instead.
        let g = SnapshotGraph::new()
            .with(Snapshot::root(s(810)))
            .with(Snapshot::child_of(s(811), s(810)))
            .with(Snapshot::child_of(s(812), s(810)));

        assert!(g.is_descendant_or_self(s(812), s(810)));
        assert!(
            !g.is_descendant_or_self(s(812), s(811)),
            "derived state built on an abandoned branch must not be reused"
        );
        assert!(!g.is_descendant_or_self(s(811), s(812)));
    }

    #[test]
    fn unknown_snapshots_are_never_descendants() {
        let g = linear();
        assert!(!g.is_descendant_or_self(s(999), s(810)));
        assert!(!g.is_descendant_or_self(s(810), s(999)));
    }

    #[test]
    fn a_parent_cycle_does_not_hang() {
        let mut g = SnapshotGraph::new();
        g.insert(Snapshot::child_of(s(1), s(2)));
        g.insert(Snapshot::child_of(s(2), s(1)));
        assert!(!g.is_descendant_or_self(s(1), s(3)));
    }

    #[test]
    fn appending_files_is_purely_additive() {
        let g = linear();
        let diff = g.diff(s(810), s(812)).expect("known snapshots");
        assert_eq!(diff.added, BTreeSet::from([f("b"), f("c")]));
        assert!(diff.removed.is_empty());
        assert!(diff.redeleted.is_empty());
        assert!(diff.is_purely_additive());
    }

    #[test]
    fn a_delete_only_commit_is_detected() {
        // No data file is added or removed: only the deletes on "a" change.
        let g = SnapshotGraph::new()
            .with(Snapshot::root(s(810)).with_clean_file(f("a")))
            .with(Snapshot::child_of(s(811), s(810)).with_file(f("a"), DeleteState(7)));

        let diff = g.diff(s(810), s(811)).expect("known snapshots");
        assert_eq!(
            diff.redeleted,
            BTreeSet::from([f("a")]),
            "a commit that only adds delete files changes which rows are live"
        );
        assert!(diff.added.is_empty());
        assert!(diff.removed.is_empty());
        assert!(
            !diff.is_purely_additive(),
            "derived state cannot be repaired by reading more; rows must be removed"
        );
    }

    #[test]
    fn compaction_removes_files_and_is_not_additive() {
        let g = SnapshotGraph::new()
            .with(
                Snapshot::root(s(810))
                    .with_clean_file(f("small-1"))
                    .with_clean_file(f("small-2")),
            )
            .with(Snapshot::child_of(s(811), s(810)).with_clean_file(f("merged")));

        let diff = g.diff(s(810), s(811)).expect("known snapshots");
        assert_eq!(diff.added, BTreeSet::from([f("merged")]));
        assert_eq!(diff.removed, BTreeSet::from([f("small-1"), f("small-2")]));
        assert!(!diff.is_purely_additive());
    }

    #[test]
    fn diffing_a_snapshot_against_itself_is_empty() {
        let g = linear();
        let diff = g.diff(s(812), s(812)).expect("known snapshots");
        assert!(diff.is_empty());
        assert!(diff.is_purely_additive());
    }

    #[test]
    fn diffing_an_unknown_snapshot_yields_nothing() {
        let g = linear();
        assert!(g.diff(s(810), s(999)).is_none());
        assert!(g.diff(s(999), s(810)).is_none());
    }

    #[test]
    fn an_empty_commit_log_drains_to_nothing() {
        assert!(Commits::new().drain().is_empty());
    }

    #[test]
    fn commits_collapse_to_the_newest_per_table() {
        let commits = Commits::new();
        commits.note(t("a"), s(810));
        commits.note(t("a"), s(812)); // out of order with the line below
        commits.note(t("a"), s(811));
        commits.note(t("a"), s(812)); // a duplicate is harmless
        commits.note(t("b"), s(900));

        let latest = commits.drain();
        assert_eq!(latest[&t("a")], s(812));
        assert_eq!(latest[&t("b")], s(900));
        assert_eq!(latest.len(), 2);
        assert!(commits.drain().is_empty());
    }
}
